INSERT INTO `sys_oper_log` VALUES (856, '职位管理', 1, 'com.ruoyi.web.controller.alone.JobsController.add()', 'POST', 1, '幸福科技', NULL, '/operate/jobs', '127.0.0.1', '内网IP', '{\"companyId\":10,\"createTime\":\"2026-02-01 20:36:50\",\"education\":\"硕士\",\"experience\":\"1-3年\",\"id\":1,\"jobDescp\":\"<h4>岗位职责:</h4><ul><li>1.带领电销团队通过电话主动联系客户，推介产品并引导客户完成交易；</li><li>2.处理客户的咨询和问题，确保和客户关系的维护；</li><li>3.跟踪和分析销售数据，以达到销售目标和业绩提升。</li></ul><h4>任职要求:</h4><ul><li>1.具备出色的团队管理能力，能够指导团队较好地运用沟通技巧，能够有效进行客户沟通；</li><li>2.具有良好的团队合作精神，能够与团队成员有效协作；</li><li>3.有互联网金融贷款类产品电销团队管理经验者，优先考虑；</li><li>4.具备较强的客户服务意识，能够在高压环境下保持积极态度；</li><li>5.愿意接受挑战，对新知识和业务模式有较高学习能力和适应能力。</li><li>6.愿意接受挑战，对新知识和业务模式有较高学习能力和适应能力。</li></ul><p><br></p>\",\"jobLabels\":\"五险一金,定期体检\",\"jobType\":\"全职\",\"name\":\"Java开发工程师\",\"params\":{},\"salaryMax\":26000,\"salaryMin\":12000}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-02-01 20:36:50', 70);
