INSERT INTO `t_job_temp` VALUES ('福州数创工坊科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10206/10205175/183712803258276514270_300.png?1772417078825', '互联网/电子商务', '少于50人', '初级数据开发工程师', '全职', '1-2年', 6000, 7000, '大专', '招聘人数： 1人\n工作地点： 福建省福州市\n用工类型： 长期员工（试用期3个月）\n薪资范围： 具体面议\n________________________________________\n核心职责 \n1.	政务数据资产目录与数据中台支持（数据资产目录、数据治理方向）\n参与政务数据资产资源目录平台的日常开发与维护，协助实现数据资源的编目、注册、发布等功能。\n支持数据中台后台数据处理流程，包括数据采集、清洗、转换、加载（ETL/ELT），保障数据的一致性和可用性。\n2.	ETL调度与数据处理\n开发、维护及优化ETL调度任务，编写和调试数据转换脚本，确保数据处理任务高效稳定运行。\n参与数据质量监控与校验，协助完成数据质量问题分析及整改方案的实施。\n3.	国产化工具与数据库适配\n使用Python及相关工具进行数据开发，适配国产数据库（如达梦、OceanBase、GaussDB、DataBend等）及大数据平台。\n参与数据治理工具（如元数据管理、数据血缘追踪）的模块开发，支持国产化替代方案的技术落地。\n________________________________________\n任职要求 \n必备技能 \n•	编程与数据处理：\n掌握Python语言，能使用国产数据库进行数据处理，具备ETL脚本开发能力。\no	熟悉SQL语法，能编写复杂查询语句并进行基本的性能优化。\n•	数据中台与工具链：\n了解ETL调度工具（如Kettle、DataX）或大数据组件（如Hadoop、Spark），有实际项目或课程经验者优先。\n具备数据治理基础知识，如元数据管理、数据质量评估等。\n•	国产化适配：\n熟悉至少一种国产数据库（如达梦、DataBend、人大金仓），具备基础开发能力。\n经验与软实力 \n•	学历经验：大专及以上学历，计算机或相关相关专业，1-2年数据开发经验（优秀应届生可放宽）。\n•	业务理解：了解政务数据治理基本概念（如数据分类分级、资产目录体系），能快速学习政务业务逻辑。\n•	综合素质：逻辑清晰，具备问题解决能力和团队协作精神，能适应政务项目的规范流程。\n________________________________________\n薪资福利 \n•	薪资结构：月薪+绩效奖金。\n•	福利保障：五险一金、带薪年假、国产化技术专项培训。\n•	试用期：3个月，薪资福利按正式标准执行。\n________________________________________\n备注说明 \n•	岗位涉及政务数据安全管理，需通过背景审查及合规培训。\n•	技术栈以Python为主，需同时支持数据中台后端处理及国产化工具链适配', '带薪年假,绩效奖金,五险一金', '1');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '标准管理岗', '全职', '5年及以上', NULL, NULL, '本科', '岗位职责：\n1）承担或参与开发标准的立项、制修订和征集意见工作，定期对开发标准化活动领域进行梳理，开展开发标准相关子领域的标规文件制定、修订等工作；执行已发布的开发标准化相关标规文件，提出标规文件执行中的意见及建议。\n2）开展开发标准落地实施工作，负责对实施项目中开发标准的执行情况进行审核。\n3）落实开发标规文件的宣传和培训工作。\n\n任职要求：\n1、具备5年以上软件开发经验，有扎实的技术功底；\n2、具备优秀的沟通协调能力、技术理解力。\n3、具备以下一项或多项技能经验。\n （1）熟悉DevOps平台的架构设计和系统研发工作，包括但不限于代码托管、CI/CD流水线、单元测试、自动化测试、安全测试等；熟悉Jenkins、Gitlab、Artifactory、SonarQube等工具的使用。\n （2）熟悉应用开发所需工具、集成开发环境、基础框架、基础服务支撑能力等工具平台。\n （3）具备数据标准相关实施、管理经验。\n工作地点：上海、成都、福州', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('福建省启博安全管理工程科学技术研究中心', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10200/10199532/1951397045290483147_300.png?1772096049909', '建筑/建材/工程', '150-500人', 'AI应用开发工程师Dify方向', '全职', '2-3年', 7000, 12000, '大专', '1. 负责企业AI智能体、AI助手产品的开发、迭代与上线。\n\n2. 基于独立完成 Dify 平台对话流程、知识库、工作流配置与API发布。\n\n3. 负责接口开发、系统对接，实现低代码平台与AI系统的数据互通。\n\n4. 独立完成项目部署、测试、问题排查与维护。\n\n5. 与业务团队配合，将业务需求转化为技术实现，独立负责技术全流程。\n\n任职要求\n\n1. 大专及以上，计算机相关专业，2～3年以上实际开发经验。\n\n2. 熟练使用 Python，能独立开发接口、对接第三方系统。\n\n3. 了解大模型API调用，有AI应用落地经验。\n\n4. 能独立使用 Dify 完成AI智能体开发与部署。\n\n5. 有低代码平台（宜搭、简道云、明道云等）对接经验优先。\n\n6. 能独立负责项目，抗压能力强，沟通顺畅，责任心强。', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('上海博为峰信息技术有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/217/216909/c8273e253b57fdcbeaa02f4160b6d82c.jpg', '计算机软件', '1000-5000人', 'Python开发（远程面试）', '全职', '3年及以上', 13000, 16000, '本科', '岗位要求：\n1. 计算机科学、信息技术、统计学、数学或相关领域本科及以上学历，相关工作经验3年以上；\n2. 熟悉Pandas、NumPy、SQL，熟悉数据ETL流程与常见数据结构；\n3. 具备Python、Java、Go等编程语言经验（掌握至少两项）；\n4. 熟悉至少一种主流数据仓库技术（如Hive, Spark, Flink，Clickhouse等），对大数据处理框架（如Hadoop, Spark等）有一定了解和实践经验。\n5. 代码风格整洁，具备良好的软件工程协作能力，具备良好的沟通能力和文字撰写能力。\n6. 具备云原生知识，拥有Docker与K8S实践经验者优先。\n\n工作职责：\n1. 参与运维数据分析平台开发，负责数据指标开发与数据平台基础设施建设。\n2. 根据业务需求设计并实施数据抽取、转换、加载流程，确保数据准确性、完整性和及时性。\n3. 基于业务需求，制作各类数据报表和仪表盘，为决策提供数据支持。\n4. 参与建立并实施数据质量监控机制，定期检查数据质量，及时发现并解决问题。\n5. 协助编写技术文档，包括数据处理流程、数据字典、技术架构设计等。\n6. 参与数据项目规划、需求分析、技术选型等，探索并应用新技术，持续优化数据处理流程。', '五险一金,交通补贴,餐饮补贴,通讯补贴,定期体检', '1');
INSERT INTO `t_job_temp` VALUES ('宁波东海集团有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/304/303505/366d9704f90627b35f3f674e9625058e.jpg', '仪器仪表/工业自动化', '1000-5000人', '大数据数据仓库开发', '全职', '3年及以上', 10000, 20000, '本科', '岗位内容：\n1、负责建设数据仓库架构，包括元数据管理、ETL调度、数据集成、OLAP等子系统的设计和开发；\n2、搭建和维护数据仓库表，解决业务人员在仓库系统流程、工具使用、数据处理等遇到的问题；\n3、基于对数据的理解和业务需求，对数据进行整理、分析和挖掘。\n岗位要求：\n1、全日制本科学历，计算机、数学、统计学相关专业；3年相关经验；\n2、熟练使用SQL语言，具有2年以上数据仓库、报表系统等ETL开发、维护经验；\n3、熟悉主流的关系型数据库及MPP数据库，至少精通一门数据库，熟悉Gbase优先；\n4、熟悉Hadoop、SparK、Hive、Hbase等大数据技术者优先。', '绩效奖金,节日福利', '1');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '测试开发工程师', '全职', '无需经验', NULL, NULL, '本科', '1、测试中台软件开发；\n2、脱敏算法、智能测试算法、数据模拟算法研究；\n3、敏感信息检测工具与平台集成开发工作。\n1、精通Java、C、PYTHON、Shell等至少两门开发语言；\n3、对数据处理或算法研究有一定经验；\n4、热爱研发工作、对工具平台建设与研究有较高兴趣。\n5、具有良好的职业道德，遵纪守法，品行端正，有进取精神，有良好的沟通协作能力和团队意识，能够承担工作压力。\n\n注：有金融业务经验的优先，包括但不限于零售金融，企业金融，同业金融等业务经验。', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('中创（芜湖）企业管理有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10102/10101075/12082077428500418925_300.png?1765266084484', '仪器仪表/工业自动化', NULL, '奇瑞数据开发分析工程师', '全职', '3-5年', 8000, 11000, '大专', '【工作内容】\n- 负责公司业务数据的采集、清洗、存储及分析，支持业务决策；\n- 参与构建数据模型和数据分析系统，提升数据处理效率；\n- 协助业务部门进行数据驱动的策略制定与优化；\n- 持续优化数据平台架构，提升数据质量与可用性。\n【任职要求】\n- 大专及以上学历，计算机、数学、统计学或相关专业优先；\n- 熟悉SQL、Python等编程语言，具备良好的逻辑思维能力；\n- 对数据挖掘、数据分析有基本了解，有相关项目经验者优先；\n- 具备良好的沟通能力和团队协作精神，责任心强。', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('福建大娱号信息科技股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3934/3933545/3933545_120.gif?635979689471404703', '计算机软件', '50-150人', '人工智能', '全职', '2年及以上', 8000, 12000, '本科', '方向：图像检测识别、NLP、开源大模型\n\n工作内容：\n1. 负责开发图像检测、识别，大语言模型应用；\n2. 负责特定arm linux终端算力设备模型移植、测试；\n\n要求：\n1、本科及以上学历，计算机、人工智能、电子、通信等相关专业，2年及以上相关工作经验；有项目经验；\n2. 会linux操作命令，了解linux系统；\n3. 熟练使用python语言，熟练使用torch, tf等AI框架，熟练使用numpy，opencv，pandas等相关工具类库\n4. 有yolo经验，熟悉或了解大语言模型的发展趋势，熟悉agent、RAG、ollama、dify、LoRA、向量等LLM技术或平台、工具，了解AI最新发展趋势\n5. 有探索精神，做事认真负责、灵活，适应不定期加班\n\n职位福利：五险一金、带薪年假、其他商业险、餐补、年终奖金', '五险一金,年终奖金', '1');
INSERT INTO `t_job_temp` VALUES ('闽都创新实验室', 'https://img01.51jobcdn.com/fansImg/CompLogo/7/6695/6694928/1650247455837_300.jpeg?1650247634691', '学术/科研', '150-500人', '算法软件工程师', '全职', '2年及以上', 12000, 20000, '硕士', '【工作内容】\n负责雷达算法信号处理和算法数据处理软件设计\n【任职要求】\n1.计算机、应用数学、信号、通信等相关专业硕士及以上；\n2.具备良好的数学基础，熟练掌握C++、Python语言及编程技巧及Matlab丁具\n3、有雷达信号处理算法、目标检测跟踪算法ARPA算法软件开发经验者优先', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('福州领视网络科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/5/4126/4125938/47477610886515525372_300.png?1660381487398', '计算机软件', '少于50人', 'AI应用开发工程师', '全职', '1年及以上', 12000, 20000, '本科', '职位描述：\n1、使用LLM（大语言模型）、向量数据库、Agent架构等AI技术栈，以及Vue、React等前端应用技术栈进行公司Agent应用构建平台的开发。\n2、快速学习并掌握前沿技术栈和技术方案，并将其应用于公司产品研发中。\n3、负责技术难点攻关和关键模块的研发，确保技术方案的可执行性和可扩展性。\n4、配合产品经理，理解并实现产品需求，确保项目的如期交付。\n5、编写高质量的技术文档和操作手册，确保团队成员的知识共享和后续维护。\n\n任职要求：\n1、计算机科学、人工智能、软件工程或相关专业本科及以上学历，优秀者可放宽要求；\n2、爱折腾、勇于挑战，具有极强的学习能力和抗压能力，能够快速适应公司的开发环境和业务需求；\n3、具备扎实的编程基础，掌握 Web前后端（如React、VUE）等技术栈；\n4、热爱编程，善于思考和解决问题，对产品质量有高度的责任心和自我要求；\n5、具有较强的团队协作能力；', '五险一金,员工旅游,绩效奖金,年终奖金,股票期权,定期体检,专业培训', '1');
INSERT INTO `t_job_temp` VALUES ('中国平安财产保险股份有限公司福建分公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2013/2012172/2012172_300.jpg?637447661494861322', '保险', '1000-5000人', '数据岗', '全职', '无需经验', 7000, 10000, '本科', '工作职责 :\n1.基础数据建设，底层数据挖掘，自动化报表搭建；\n2.机构、渠道相关业务经营推动及问题剖析，预警并督导问题指标改善；\n3.领导交办的其它工作。\n \n\n任职资格 : \n1.本科及以上学历； 数学、统计、计算机等相关专业优先；\n2.工作严谨、认真，责任心强；\n3.具有良好的沟通协调能力、较强的逻辑思维能力，责任心强，执行力高；\n4.熟练操作PPT、EXCEL等常用办公软件，具有一定数据分析能力优先。', '五险一金,绩效奖金,年终奖金,定期体检,专业培训,带薪年假,节日福利', '1');
INSERT INTO `t_job_temp` VALUES ('中电福富信息科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/61/60407/d1fb1069bbca0f331c1e2af0767696db.jpg', '计算机软件', '1000-5000人', 'Python开发工程师-福州', '全职', '3年及以上', 8000, 15000, '本科', '工作概述：\n1.负责AI能力模型的服务化封装；\n2.独立承担项目需求分析，完成模块设计、编码、调试以及单元测试工作，确保软件质量与性能达到预期标准；\n3.编写技术文档和维护代码库，确保代码的可读性和可维护性；\n4.参与LLM的数据清洗，数据优化工作；\n5.参与NLP相关的算法设计、模型训练、模型调优、模型部署等；\n6.参与基础NLP能力建设，如长/短文本分类、Embedding等相关技术；\n7.具备良好的团队协作精神，能够与团队成员共同解决技术难题，推动项目的顺利进行。\n\n任职要求：\n1.计算机相关专业本科及以上学历，3年以上相关工作经验；精通Python服务端开发熟练掌握numpy、pandas等数据处理框架；\n2.熟悉web开发框架（fastapi/flask/django），熟悉Linux操作系统及shell编程；\n3.熟悉mysql，redis，oracle等常用数据库，具有数据库开发和设计能力；\n4.熟悉Docker等容器类中间件，熟悉基于docker开发部署服务的流程;\n5.熟悉Linux系统，能够离线解决Linux中开发环境问题；\n6.有NLP相关AI落地项目经验者优先；\n7.有NLP大模型训练经验者优先，如BERT、 GPT等LLM等相关经验优先。', '五险一金,带薪年假', '1');
INSERT INTO `t_job_temp` VALUES ('福建顶点软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1546/1545107/1545107_120.gif?636501560681636985', '计算机软件', '1000-5000人', '金融数据开发工程师(AMB01E05)', '全职', '2-5年', 8000, 16000, '本科', '岗位职责:\n1、参与项目需求分析，理解业务需求并转化为详细需求文档；\n2、在团队的指导下，用技术实现业务需求，确保代码质量符合团队标准； \n3、了解并持续学习金融工程相关知识，将原始数据转化为产品/项目需要的业务指标；\n4、负责编写相关技术文档，包含但不限于：需求、详细设计、技术方案及操作手册等，促进团队沟通与协作。\n任职要求:\n1、具有大学本科及以上学历，计算机、数学、金融工程相关专业毕业；\n2、具有2-5年软件开发相关工作经验，优秀应届毕业生亦可；\n3、熟练掌握Java或Python编程语言，以及Oracle/Mysql等关系型数据库的使用；\n4、具备出色的沟通能力和良好的团队合作精神，能够与各团队成员有效沟通，共同解决问题；\n5、具备高度责任心，对待工作严谨认真，确保任务的高质量完成；\n6、有基金/证券从业资格证或金融科技行业相关工作经历者优先。', '员工旅游,年终奖金', '1');
INSERT INTO `t_job_temp` VALUES ('福州领视网络科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/5/4126/4125938/47477610886515525372_300.png?1660381487398', '计算机软件', '少于50人', '全栈开发工程师（Python/PHP + 前端方向）', '全职', '2年及以上', 8000, 16000, '本科', '岗位职责:\n\n前后端开发\n负责公司Web平台、小程序及移动端应用的全栈开发，包括需求分析、架构设计、代码实现与维护。\n使用Python/PHP完成后端业务逻辑开发。\n基于Vue.js、jQuery等框架完成前端交互开发，确保页面高效渲染与用户体验。\n\n跨平台开发\n使用UniApp框架开发多端兼容的小程序（微信、支付宝等）及APP，解决不同平台的适配与性能问题。\n熟悉微信小程序生态，包括支付、地图、授权等接口开发与维护。\n\n技术优化与协作\n优化现有系统性能，解决浏览器兼容性、数据解析效率等问题。\n配合测试团队完成功能验证，协同产品经理迭代需求，输出技术文档。\n\n任职要求\n技术能力\n后端：精通Python/PHP，熟悉FastAPI/CodeIgniter/ThinkPHP等框架，掌握MySQL/Redis数据库设计与优化。\n\n前端：扎实的HTML/CSS/JavaScript基础，熟练使用Vue全家桶（Vuex、Vue Router）、jQuery，了解Webpack/Vite等构建工具。\n跨平台：具备UniApp实战经验，熟悉小程序生命周期、原生组件封装及热更新机制。\n\n经验要求\n2年以上开发经验\n\n软性要求\n良好的代码规范、文档习惯及团队协作意识，能承受项目压力。\n对新技术敏感，主动学习前沿工具', '五险一金,员工旅游,绩效奖金,年终奖金,股票期权,定期体检,专业培训', '1');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '大数据开发工程师', '全职', '2年及以上', NULL, NULL, '本科', '岗位职责：\n\n1、参与基于Hadoop的大数据平台的研发工作与持续优化工作。\n2、参与大数据平台的容量规划、持续交付、业务监控、应急响应，保证平台正常运行。\n3、利用大数据相关技术实现对数据的分析、挖掘、处理、及数据可视化等相关工作。\n4、学习和研究新技术以满足系统需求。\n\n岗位要求：\n\n1、拥有数据处理相关专业背景。\n2、对互联网产品有见解，关注前沿技术，有较强的学习能力、分析能力和动手能力。\n3、熟悉常用分布式计算和存储框架，如Hadoop/HDFS/Spark等。\n4、至少熟悉以下一种大数据技术组件，Hive、Impala、Hbase、Flume、Kafka、Zookeeper、Storm、Flink。熟悉资产管理、资金业务和金融工程相关领域业务者优先。\n5、个性乐观开朗，沟通能力强，具备良好的团队协作精神，能利用自身技术能力提升团队整体研发效率。\n6、多份工作经历需最近2份工作均满2年，或最近1份工作经历满3年。仅有一份工作经历的需满两年。\n工作地点：上海、成都', '五险一金', '1');
INSERT INTO `t_job_temp` VALUES ('华福证券股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3870/3869840/3869840_300.png?637672046133833281', '金融/投资/证券', '1000-5000人', '数据治理岗', '全职', '5年及以上', 15000, 20000, '本科', '岗位职责\n1、参与公司数据治理体系和制度流程建设工作，负责根据公司制定的数据标准，设计数据模型，推动数据管控策略实施。\n2、推动数据治理相关模块工作，包括元数据管理、数据标准管理、数据质量管理和数据资产管理等。\n3、持续推动数据治理相关系统功能完善，组织需求规划和功能验证等工作。\n4、持续引导各领域数据治理专员开展数据治理工作，推动数据资产管理和价值输出。\n5、组织开展数据治理相关宣传和培训。\n\n任职要求\n1、本科及以上学历，经济、数学、统计学，计算机学等相关专业；\n2、熟悉数据治理实施方法，至少拥有元数据管理、数据标准管理、数据质量管理和数据资产管理中1个模块的实践经验。\n3、五年以上大型金融、互联网企业的数据开发、数据管理工作经验，具有证券行业建模经验者优先。\n4、至少掌握一门常用数据处理脚本语言， 如SQL\\PYTHON，熟悉基于该语言的常用开源算法；\n5、具有较强的逻辑思维能力、数据挖掘分析能力，具备良好的敬业精神，有较强的团队协作能力、沟通能力和问题分析能力等。', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('前锦网络信息技术（上海）有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/9/8943/8942798/167332862891016813763_300.png?1770087169753', '专业服务(咨询、人力资源、财会)', '5000-10000人', 'AI 应用工程师', '全职', '3年及以上', 15000, 25000, '硕士', '岗位职责：\n1、 针对光学与光机装配产品，设计可提升精度/良率的 AI 模型应用方案（含需求拆解与技术\n选型），并推动方案从原型验证到产线落地。\n2、 负责面向光学行业的 AI 模型开发，如光学缺陷识别、工艺参数优化、元件性能预测等。\n3、 根据光学数据特点进行数据预处理与特征工程，持续优化模型精度与推理效率。\n4、 贯通光学-光机组件全制造流程数据，利用数据挖掘方法释放数据价值。\n5、 跟踪前沿 AI 技术与数据挖掘工具，评估其在光学制造场景中的落地可行性。\n6、 撰写技术文档，为工程与生产团队提供技术支持。\n岗位要求：\n1、 硕士及以上学历，计算机、人工智能、数据科学、电子信息、光学工程、光电信息科学与\n工程等相关专业，博士优先。\n2、 3 年以上 AI 应用开发经验，其中至少 1 年从事光通信、激光、镜头或光学检测设备等光学\n制造相关技术岗位。\n3、 熟练使用 AI 与数据挖掘工具，了解工业云平台 AI 服务或边缘 AI 部署方案。\n4、 至少精通 Python、 Java、 C++中的一种编程语言。\n5、 熟练掌握数据挖掘方法（关联、聚类、回归、异常检测等）。\n6、 熟悉机器学习算法，了解模型微调、压缩及图像预处理技术。\n7、 熟悉大数据处理工具及数据分析库，可对光学批量数据高效清洗、转换与分析。\n8、 具备基础光学知识（几何光学、光纤、光学成像原理），了解光学制造流程，能快速理解\n现场工艺。\n9、 英语听说读写熟练。\n10、 乐于持续学习新知识、新技术与新理念。', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('福州领视网络科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/5/4126/4125938/47477610886515525372_300.png?1660381487398', '计算机软件', '少于50人', 'AI开发工程师', '全职', '无需经验', 8000, 16000, '本科', 'AI开发工程师（可应届/实习）6767\n\n参与机器学习/深度学习模型的训练、调优及部署（如NLP、CV、大模型应用）；\n使用TensorFlow/PyTorch等框架实现算法原型，并完成性能优化；\n协助将AI模型集成至产品（如API服务、智能问答系统）。\n\n参与数据清洗、标注及特征工程，构建高质量数据集；\n\n跟踪大模型（LLaMA、GPT）、Agent技术、RAG架构等方向，参与技术验证。\n\n大模型应用：微调开源模型（如Qwen）、开发RAG知识库、Agent工具链；\n垂直领域AI：结合农业、环保等行业需求开发定制化AI功能；\nAI产品辅助：参与Prompt优化、数据标注、多模态交互功能开发。\n\n技术能力\n编程基础：精通Python；\nAI框架：掌握TensorFlow/PyTorch基础，有模型训练调参经验者优先；\n工程基础：了解RESTful API、数据库（SQL/NoSQL）、Linux基础命令；\n算法理论：理解CNN/RNN/Transformer等经典模型原理', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '性能测试工程师', '全职', '无需经验', NULL, NULL, '本科', '1、负责金融类信息系统的性能测试和调优工作。\n2、负责性能测试需求分析、性能测试场景设计、测试数据准备、测试脚本编写和执行、性能测试数据分析和问题排查，以及性能优化建议和验证等相关工作；\n3、负责性能测试过程管理以及沟通、协调、报告编制和汇报等工作；\n4、负责性能测试技术、方法和工具的研究及推广，推进性能测试能力建设。\n\n\n1、熟练掌握LoadRunner、Jmeter等性能测试工具及应用；\n2、熟练掌握性能监控技术，能够利用Prometheus、nmon、Arthas、jvisualvm等系统监控工具对应用、数据库、中间件等的系统资源进行监控，能够利用pinpoint、skywalking等APM工具进行应用链路追踪；\n3、熟悉系统主流技术架构，对分布式、微服务、云原生、高可用及多活等技术架构有一定的理解和应用；\n4、具有一定的应用软件开发基础，熟悉Java、Python、C++等至少一门主流编程语言；\n5、了解TD/TxSQL、Oracle、Informix等数据库，Linux、AIX等操作系统，Weblogic、NG、ZooKeeper、Redis、MQ等中间件的应用性能和参数调优；\n6、具备性能分析能力，能定位性能问题，提出性能优化方案或意见。\n\n注：有金融业务经验的优先，包括但不限于零售金融，企业金融，同业金融等业务经验。', NULL, '1');
INSERT INTO `t_job_temp` VALUES ('贵州瀚溯信息咨询服务有限公司', 'https://img04.51jobcdn.com/im/mkt/app/51job_phone/app/homelogo/new/home_logo_default_imnetwork.png?version=20241112', '通信/电信/网络设备', NULL, '大数据分析师', '全职', '无需经验', 7000, 12000, '大专', '1.收集并整理销售数据并进行分析。\n2.负责常规业务数据提取、处理及分析工作。\n3.数据库营销活动数据提取和分析。\n4.负责数据处理和通报，并及时反馈。', '五险一金,员工旅游,交通补贴,餐饮补贴,通讯补贴,专业培训,绩效奖金,年终奖金,定期体检', '1');
INSERT INTO `t_job_temp` VALUES ('福建新大陆软件工程有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/67/66190/b5bded9ac03af6021cbf0bf0a43d093e.jpg', '批发/零售', '1000-5000人', '算法工程师', '全职', '2年', 15000, 20000, '硕士', '岗位职责：\n1、负责多模态大模型的训练、调优工作;\n2、结合实际应用场景，提供自然语言处理、深度学习等技术解决方案，与大数据技术相结合支撑相关应用建设;\n3、为应用和业务人员提供相关培训和应用指导;\n4、发掘并编写相关技术专利。\n\n岗位要求：\n1、要求计算机相关专业，硕士学位；\n2、有生成式模型的落地经验，了解已有的预训练模型；\n3、熟悉python编程，熟悉朴素贝叶斯，贝叶斯网络，线性回归，逻辑回归，决策树，遗传算法，聚类算法等传统机器学习算法和神经网络等深度学习算法；\n4、具备较强的逻辑思维、沟通表达、团队合作能力，良好的文档、代码书写习惯；\n5、对算法、人工智能有浓厚兴趣，如有建模竞赛获奖者优先;\n6、可出差优先', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建新大陆软件工程有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/67/66190/b5bded9ac03af6021cbf0bf0a43d093e.jpg', '批发/零售', '1000-5000人', '软件测试', '全职', '1年及以上', 7000, 11000, '本科', '岗位职责：通信行业软件测试及相关工作。\n\n任职要求：\n1、本科及以上学历，计算机相关专业毕业；\n2、熟悉软件工程和测试理论，熟练掌握测试用例设计方法，对测试工作有浓厚兴趣；\n3、熟练掌握至少两门编程语言（Java/C++/python）,能应用到日常测试开发中；\n4、至少熟练掌握一种测试工具（Jmeter，Selenium，Appium、Robot等）；\n5、熟悉UNIX/LINUX操作系统，了解UNIX常用命令，会编写shell脚本；\n6、熟练使用数据库（ORACLE/SQLSERVER/MYSQL）的一种；\n7、有良好的沟通能力、逻辑分析能力、执行能力，做事耐心，细心，责任心强；\n8、有自动化测试、性能测试经验者优先；\n9、有运营商行业从业背景者优先。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建新大陆软件工程有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/67/66190/b5bded9ac03af6021cbf0bf0a43d093e.jpg', '批发/零售', '1000-5000人', '高级Java工程师', '全职', '5年及以上', 14000, 16000, '本科', '岗位职责：\n1、参与项目系统设计，完成软件项目的程序开发工作；\n2、负责客需到产需的分析、设计（包含原型设计）和文档编写；\n3、负责根据产需和设计进行软件开发，并能够协调组员进行协同开发；\n4、负责对其负责项目进行全方位技术栈解释\n岗位要求：\n1、	5年及以上工作经验，有电信行业软件经验优先；\n2、	精通JAVA编程语言，熟悉多线程、分布式、RPC解决方案；精通Spring、SpringMVC、MyBatis、SpringBoot、SpringCloud等JAVA主流框架；有python语言开发经验优先；\n3、	熟悉oracle、MySQL或Redis等数据库，有数据库设计经验、熟悉数据库设计规范以及有国产数据库经验优先；\n4、	熟悉软件产品开发、系统业务架构的设计流程，直接负责或参与过软件项目的对应架构设计和开发；\n5、	熟悉Docker、K8S，有基于容器平台进行企业级分布式系统部署和实践经验者优先；\n6、	掌握分布式系统设计原理，具备大规模分布式系统或微服务系统的开发，调优和设计经验优先；\n7、	有业务架构和技术架构能力，并能指导团队落地架构、识别系统建设痛点，针对性的制定实施治理方案者优先；\n8、	具备良好的沟通能力、协调能力、问题解决能力以及责任心，有能力携带小组成员完成项目开发与交维。', '免费健身,免费班车,健身房,五险一金,员工旅游,年终奖金,定期体检', '0');
INSERT INTO `t_job_temp` VALUES ('宁波东海集团有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/304/303505/366d9704f90627b35f3f674e9625058e.jpg', '仪器仪表/工业自动化', '1000-5000人', '软件测试工程师', '全职', '1-3年', 6000, 10000, '本科', '岗位内容：\n1、根据软件需求进行测试用例设计与维护；\n2、实施测试，并对发现BUG进行追踪；\n3、根据测试结果完成测试报告。\n岗位要求：\n1、本科学历，计算机等相关专业；\n2、熟悉软件测试理论和测试技术，热爱软件测试工作。', '绩效奖金,节日福利', '0');
INSERT INTO `t_job_temp` VALUES ('瑞芯微电子股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1291/1290776/1290776_300.png?637235176253118983', '电子技术/半导体/集成电路', '1000-5000人', '机器学习推理部署工程师-福州 (MJ000573)', '全职', '2年及以上', 25000, 50000, '硕士', '岗位职责\n1、参与深度学习编译器中计算图切分算法、约束传播与搜索策略的设计与优化；\n2、面向 Transformer / LLM 等模型，解决分布式推理与并行中的核心技术问题；\n3、针对特定RK自研的NPU/AI加速器架构，设计高效的内存规划、算子调度与多核通信策略；\n4、分析推理性能瓶颈，从算法、编译与系统层面持续提升端侧/边缘侧推理效率；\n岗位要求\n1、计算机及相关专业硕士及以上学历，2 年以上机器学习算法或工程开发经验；\n2、精通 Python，熟悉 PyTorch 框架及其计算图执行机制；\n3、具备扎实的数据结构与算法基础，熟悉 树/图遍历、搜索、约束传播等基本方法；\n4、逻辑思维清晰，能够系统性分析并解决复杂技术问题；\n5、对高性能计算与模型推理系统有持续投入的技术热情。', '五险一金,定期体检,绩效奖金,专业培训,带薪年假,补充医疗保险', '0');
INSERT INTO `t_job_temp` VALUES ('瑞芯微电子股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1291/1290776/1290776_300.png?637235176253118983', '电子技术/半导体/集成电路', '1000-5000人', '机器学习算法工程师-福州 (MJ000517)', '全职', '无需经验', 20000, 35000, '硕士', '岗位职责：\n1、 使用深度学习进行前沿人工智能技术研发，包括计算机视觉（人脸、行人、车辆等的检测、识别）、音频、自然语言处理等；\n2、 将人工智能算法应用到各种挑战性的现实场景；\n岗位要求：\n1、 物理、数学、计算机、软件工程、电子信息等相关专业硕士及以上学历；\n2、 在深度学习、统计机器学习、计算机视觉、最优化方法等方面有较深入的研究；\n3、 熟练掌握各种深度神经网络(DNN, CNN, RNN, LSTM等)，并能够将其应用于特定场景中去；\n4、 熟练使用主流的深度学习框架，如TensorFlow、Caffe、MXNet、Theano、Torch等任一种；\n5、 熟练掌握C/C++和脚本语言编程(如Shell, Python等)；\n6、 在深度学习或计算机视觉等国际会议或者期刊上发表论文、相关国际比赛获奖、有相关专利者优先。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建顶点软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1546/1545107/1545107_120.gif?636501560681636985', '计算机软件', '1000-5000人', '软件测试工程师(IOB01G08)', '全职', '1年及以上', 7000, 10000, '本科', '岗位职责:\n1、参与公司软件产品测试的全流程，包括需求分析、设计评审协作、测试计划制定、测试用例设计与执行，以及缺陷跟踪与软件质量综合分析等工作； \n2、负责执行项目测试任务，包括构建高效的测试环境，执行系统测试与回归测试，确保被测系统的稳定与质量达标； \n3、参与软件测试过程的优化与持续改进工作，共同探索并创新测试流程与方法，助力研发质量与效率的双重提升。\n任职要求:\n1、具有大学本科及以上学历、计算机相关专业毕业；\n2、具有1年及以上应用系统测试的工作经验，熟悉金融证券行业者优先；\n3、掌握计算机基础知识，熟悉软件工程原理，熟练掌握软件测试理论、方法及流程；\n4、具备基本的测试能力，涵盖测试用例设计、执行及缺陷跟踪，同时拥有性能测试、自动化测试、安全测试等至少一种测试类型的实际经验；\n5、熟悉Java编程基础知识，掌握关系型数据库的操作，能够独立编写简单的测试脚本或辅助测试工具；\n6、具备良好的逻辑思维能力，能够分析测试中的问题，并提出初步的解决方案；\n7、责任心强，具备出色的沟通能力和团队合作精神，能够积极融入团队，有效传达测试进展和问题；\n8、具备积极主动的学习态度和较强的抗压能力，愿意在快速变化的环境中不断成长。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建华东船厂有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/8/7734/7733053/26840697573084600764_300.png?1681288808171', '航天/航空', '1000-5000人', '财务副经理（数字化方向）', '全职', '5年及以上', 8000, 15000, '本科', '统筹公司数字化建设，制定泛微系统开发计划并管控进度；协调泛微供应商及公司业务部门，确保系统需求落地；定期输出数字化建设进展报告；管理部门数字化开发运维人员，制定技术培训及能力提升计划；跨部门资源整合与冲突解决能力，技术语言与业务语言的转译能力；211、985院校计算机科学、信息技术、管理信息系统或相关专业；熟悉至少一种编程语言，如Java、C++、Python等；具备前端、后端开发的基础知识。\n岗位要求：5年以上IT项目管理经验，3年以上企业数字化系统实施经验；主导过OA/ERP等系统与企业核心业务系统（如CRM、SRM）的对接项目；有泛微系统实施经验者优先。', '五险一金,定期体检,绩效奖金,餐饮补贴,通讯补贴,双休,免费班车', '0');
INSERT INTO `t_job_temp` VALUES ('瑞芯微电子股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1291/1290776/1290776_300.png?637235176253118983', '电子技术/半导体/集成电路', '1000-5000人', 'SoC验证工程师-福州 (MJ000586)', '全职', '3年及以上', 20000, 35000, '硕士', '岗位职责：\n1、负责芯片集成验证和系统验证计划制定，依据设计规格输出验证方案；\n2、负责芯片集成通路的验证与回归；\n3、负责用C、SystemVerilog等编写测试用例进行系统验证与回归；\n4、负责用Verdi定位设计缺陷，跟踪Bug修复全流程并确保闭环；\n5、负责覆盖率分析与验证报告撰写，支撑流片决策；\n6、负责与架构、设计等团队协作，参与验证方法论优化。\n岗位要求：\n1、硕士及以上学历，电子、通信、计算机、微电子或物理学专业；\n2、熟练掌握Verilog、SystemVerilog、C等语言的编程，有扎实的数字电路基础；\n3、三年以上IC设计流程的相关工作经验；\n4、熟练使用VCS、Verdi等仿真调试工具，具备Python/Shell脚本开发能力；\n5、精通SystemVerilog与UVM验证方法学，掌握AMBA系列总线协议及数字电路原理；\n6、熟悉UVM验证环境，理解SoC系统组成，了解一些常用的外设接口(如I2C、UART、SPI等)；\n7、具有较强的学习能力、沟通能力和良好的团队合作精神。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('宁波东海集团有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/baselogo/1/304/303505/366d9704f90627b35f3f674e9625058e.jpg', '仪器仪表/工业自动化', '1000-5000人', 'JAVA工程师助理', '全职', '无需经验', 6000, 8000, '本科', '职责：\n1、负责应用软件系统开发工作、后台业务系统开发；\n2、负责项目的程序设计和实施\n3、遵循公司技术标准、规范，高质量完成设计、开发任务；\n要求：\n1、2025届本科学历，计算机相关专业\n2、熟悉Java/J2EE或C#编程，有SSH或类似框架的实际项目经验，熟练使用Eclipse等开发工具；\n3、熟悉B/S三层结构开发模式，熟练使用一种以上开发框架(Spring/SpringMVC/Mybatis)；\n4、熟悉JavaScript、Ajax、XML,EXTjs等相关技术；\n5、熟悉Oracle、MySQL等数据库开发；\n6、有良好的代码书写、注释和单元测试习惯；\n7、具备良好的沟通合作技巧，较强的责任心及团队合作精神；', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', 'C/C++开发工程师', '全职', '无需经验', NULL, NULL, '本科', '岗位职责：\n\n1、负责C/C++类系统需求分析；\n\n2、负责C/C++类系统的设计和开发工作；\n\n3、负责解决系统运行中的故障和性能问题。\n\n岗位要求：\n\n1、具备扎实C/C++、Linux基础知识；\n\n2、熟悉Linux环境进行C/C++程序开发,掌握shell脚本和makefile编写；\n\n3、熟悉Linux IPC、信号等工作机制，了解多进程、多线程的开发方法；熟悉TCP/IP、HTTP、SSL等网络编程；对C开源框架有所了解；\n\n4、熟悉主流数据库中的一种或多种,如Oracle、MySQL等；有Oralce pro*c或使用C语言开发过MySQL数据库相关的应用系统经验者优先；\n\n\n5、有高并发、高负载、高可用性系统设计开发及调优经验优先；\n\n6、有银行或金融行业交易类系统开发经验者优先。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('智源芯片（杭州）科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9987/9986076/65506262212550289962_300.png?1759129325906', '计算机硬件', '50-150人', '初级软件工程师/双休', '全职', '无需经验', 8000, 9000, '大专', '【工作内容】\n- 参与公司软件产品的开发与维护，协助完成模块设计与编码工作；\n- 与团队成员协作，进行需求分析、功能实现及测试支持；\n- 学习并应用公司技术框架与开发流程，提升自身技术水平；\n- 按时完成上级分配的任务，并提交相关文档与代码。\n【任职要求】\n- 大专及以上学历，计算机相关专业优先，不限工作经验；（不招26届）\n- 具备基本的编程能力，熟悉至少一种编程语言（如Java、Python、C++等）；\n- 对软件开发流程有一定了解，具备良好的学习能力和沟通能力；\n- 工作认真负责，有责任心，能够适应团队合作与一定的工作压力。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('星耀芯科（上海）科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10089/10088863/125743733460566566421_300.png?1765159041509', '计算机硬件', '150-500人', '软件测试工程师', '全职', '无需经验', 7000, 9000, '大专', '【工作内容】\n- 参与软件产品的设计、开发与基础测试；\n- 协助进行功能模块编码、调试及问题修复；\n- 配合团队参与需求分析、技术方案沟通；\n- 协助优化产品性能，提升用户体验。\n\n【任职要求】\n- 计算机相关专业，应届生/无工作经验均可投递；\n- 热爱编程，具备基础逻辑思维能力；\n- 掌握至少一种编程语言（Java/Python/C++等均可）；\n- 沟通顺畅，有良好的团队协作意识；\n- 学习能力强，愿意主动探索新技术、快速适应团队。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('贵州瀚溯信息咨询服务有限公司', 'https://img04.51jobcdn.com/im/mkt/app/51job_phone/app/homelogo/new/home_logo_default_imnetwork.png?version=20241112', '通信/电信/网络设备', NULL, '软件测试', '全职', '无需经验', 7000, 12000, '大专', '1.参与软件测试流程的规划和执行，确保软件质量符合标准\n2.相关文档编写记录\n3.分析检测结果\n4.参与需求分析', '五险一金,年终奖金,周末双休,节日福利', '0');
INSERT INTO `t_job_temp` VALUES ('北京骐骥优才科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10051/10050331/188104478846297813415_300.png?1771992008596', '专业服务(咨询、人力资源、财会)', '150-500人', '软件工程师（初级/中级）', '全职', '1年及以上', 7000, 14000, '本科', '【工作内容】\n- 参与公司产品的需求分析、系统设计及开发工作；\n- 编写高质量、可维护的代码，完成模块开发与测试；\n- 与团队成员协作，推动项目按期交付；\n- 持续优化系统性能，提升用户体验。\n【任职要求】\n- 本科学历，计算机、电子通信、自动化、电气类等相关专业；\n- 熟悉至少一种主流编程语言（如Java、Python、C++等）；\n- 具备良好的逻辑思维能力和问题解决能力；\n- 对新技术有较强的学习兴趣和适应能力；\n- 有团队合作精神，沟通表达能力强。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福州高新区才拓科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9100/9099455/76629913596111655292_300.png?1761016387765', '计算机软件', NULL, '软件测试助理工程师', '全职', '无需经验', 8000, 12000, '大专', '工作内容：\n我们的软件测试助理工程师职位正在招聘中。作为我们的软件测试团队的一员，你将负责支持开发团队，执行软件测试计划，并确保产品质量。你将有机会参与到我们创新性的项目中，并有机会提升自己的技能和知识。\n主要职责：\n* 根据项目经理和产品经理提供需求，执行软件测试计划；\n* 协助测试经理创建测试计划、测试用例，并跟踪测试进度；\n* 分析测试结果，并撰写测试报告；\n* 参与项目设计评审，并提出合理的测试建议；\n* 负责项目中测试工具的使用及维护；\n* 协助测试团队完成其他相关工作。\n任职要求 \n男女不限 年龄20-28岁 具有大专学历以上 优先考虑理工科', '五险一金,年终奖金', '0');
INSERT INTO `t_job_temp` VALUES ('中创（芜湖）企业管理有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10102/10101075/12082077428500418925_300.png?1765266084484', '仪器仪表/工业自动化', NULL, '奇瑞产品测试工程师', '全职', '3-5年', 8000, 11000, '大专', '\"1、负责座舱系统软件测试计划和方案的策划和编制；\n2、负责座舱测试用例开发、测试工作的开展、执行和过程管理、有效性控制、完成试验报告、总结；\n3、测试问题提出、推进、回归：识别、反馈测试中发现的问题，协同各专业团队进行深入分析并跟踪问题整改情况，对整改效果进行测试验收；\n4、管控供应商的测试计划、方案、测试交付质量管理，确保供应商测试交付物按时按量按质提交。\"', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('芯途势力（厦门）集成电路科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9930/9929695/36129642829515014536_300.jpg?1756794724141', '电子技术/半导体/集成电路', '50-150人', '初级软件测试工程师/接受无经验', '全职', '无需经验', 7500, 10000, '本科', '【工作内容】\n- 负责公司软件产品的功能测试、性能测试及兼容性测试；\n- 编写测试用例，执行测试计划并记录测试结果；\n- 与开发团队协作，跟踪并推动问题修复；\n- 参与产品质量评估，协助提升产品稳定性与用户体验。\n【任职要求】\n- 本科及以上学历，计算机相关专业，需持有全日制毕业证书；\n- 对软件测试流程有一定了解，具备良好的逻辑思维能力；\n- 具备较强的学习能力和责任心，能够适应快节奏的工作环境；\n- 有相关实习或项目经验者优先，欢迎投递。', '五险一金,定期体检,专业培训,带薪年假,节日福利', '0');
INSERT INTO `t_job_temp` VALUES ('福建省数字福建云计算运营有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9501/9500890/457950618850007658692_300.png?1743498757043', '计算机服务(系统、数据服务、维修)', '50-150人', '子公司开发工程师', '全职', '5年及以上', NULL, NULL, '本科', '岗位职责：\n1.根据项目具体要求完成平台建设、测试、维护和开发文档编写；\n2.根据项目具体要求，组织参与方案讨论和技术调研、负责方案升级、更新并承担相应开发任务，完成项目任务目标；\n3.负责验证编码质量,协助测试人员完成软件系统及模块的测试，分析并解决软件开发、调试测试过程中的问题；\n4.参与云平台建设和应用开发工作。\n任职要求：\n1.大学本科及以上学历，计算机及相关专业，具备5年以上Java项目开发经验；\n2.熟悉windows、Linux等各种操作系统，具备一定的服务器、存储、网络、安全、容器及云计算知识；\n3.熟悉数据库或中间件技术，熟悉SHELL编程，具备C/C++，java，PHP或Python编程能力；\n4.具备大模型开发相关经验：了解大模型训练及推理的基本流程，熟悉至少一种大模型开发工具或框架；\n5.熟悉智算平台与大模型结合的应用场景，能协助完成大模型开发过程中的算力资源适配、性能测试等基础工作；\n6.具备较强的技术方案编写能力：能根据业务需求，梳理大模型开发、云计算资源适配等场景的技术逻辑，独立完成方案初稿，确保方案内容清晰、逻辑严谨，可支撑技术落地与跨团队同步；\n7.具备良好的沟通能力，团队合作意识，对工作有责任心，可以快速掌握新技能。', '五险一金,年终奖金,定期体检,绩效奖金,带薪年假,餐饮补贴,做五休二,通讯补贴,交通补贴', '0');
INSERT INTO `t_job_temp` VALUES ('上海医疗质量研究中心', 'https://img04.51jobcdn.com/im/mkt/app/51job_phone/app/homelogo/new/home_logo_default_healthcare.png?version=20241112', '医疗/护理/卫生', '少于50人', '科研助理（福州）', '全职', '1-5年', 6000, 12000, '本科', '核心职责：从事阿尔茨海默病等相关研究工作，进行科研项目的撰写，对于科学进展起到推动作用。\n次要职责：对于实验室相关实验仪器进行设备管理、使用、维护以及相关样本的保存、记录、使用。\n任职要求\n1.生物医学及相关专业、神经内科、神经科学或者阿尔茨海默病相关基础研究者以及精通R语言与python语言数据分析者优先。\n2.工作地点在福州\n3.英语6级，有科研经历的优先', '五险一金', '0');
INSERT INTO `t_job_temp` VALUES ('北京先进数通信息技术股份公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/1/106/105547/105547_120.gif?635762665713877419', '计算机软件', '1000-5000人', '大模型工程师（福州）(J14798)', '全职', '5年及以上', 10000, 20000, '本科', '工作职责:\n银行AI应用场景研发工程师\n主要职责：\n1、负责AI应用成果转化，与业务专家合作，了解业务产品需求并转化为大模型应用方案，主导相关应用的开发实施，负责大模型业务场景应用落地端到端工作；&nbsp;\n2、基于最新的大语言模型、多模态等技术方法，实现金融领域下游任务场景的落地应用，包括对话机器人、坐席助手、文本生成、阅读理解、数据分析等；\n3、负责金融领域具体业务场景的大模型微调、提示词工程、增强检索和智能体工作流构建等，负责模型调优和应用工程优化；\n4、跟踪并分析行业应用动态，持续优化和改进现有业务解决方案；并梳理典型案例进行业务应用推广。\n\n任职资格:\n1、计算机、人工智能相关专业，本科5年以上工作经验\n2、至少参与过3个以上的AI项目经历。\n\n技能\n1、具备深度学习、NLP算法、微调、强化学习的基础知识；&nbsp;\n2、熟悉企业级人工智能平台的研发流程，涵盖数据处理DataOps、训练推理LLMOps和应用研发三大能力，建立大模型技术落地的系统化支撑； \n3、熟悉熟悉Prompt、Rag、Agent的基本原理和应用方法；\n4、掌握知识问答、文本理解、文档生成、智能调度大模型主流应用范式；\n5、熟练使用Python、Java编程开发语言，Pytorch、PaddlePaddle、Tensorflow 等深度学习框架；\n6、关注行业和技术发展趋势，跟踪并分析、了解行业内大模型平台及领域应用平台发展动态。\n热爱学习新技术并结合业务进行过落地实践，良好的沟通协同能力，有高度的责任感、团队合作和敬业精神，具备较强的推动能力。&nbsp;\n\n岗位竞争优势：银行AI应用场景，有真实案例实践。', '五险一金,定期体检,有餐补', '0');
INSERT INTO `t_job_temp` VALUES ('福州艾迪莫智能科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/7/6437/6436460/183142125019879937231_300.png?1725354996687', '计算机软件', '少于50人', '物联网平台研发工程师', '全职', '3年及以上', 10000, 18000, '本科', '岗位职责：\n\n一、物联网平台开发\n1、负责轻量化物联网平台的设计与开发，实现设备数据接入、逻辑规则配置、报警中心、消息中心等功能；\n2、实现与数字孪生可视化平台的数据对接与映射。\n\n二、边缘网关开发\n1、开发并维护物联网边缘网关，支持多种主流协议（Modbus、BACnet、MQTT、OPC UA 等），并扩展私有协议接入；\n2、现视频数据采集、流媒体传输（RTMP/HLS/FLV）与实时压缩编码。\n\n三、系统集成与服务\n1、负责与智能化子系统（UPS、EPS、GIS 微水局放、变压器监测、避雷系统、电缆监测等）的数据对接和联动开发；\n2、提供设备监测点位配置、报警联动逻辑实现。\n\n四、业务运行管理平台\n1、基于微服务架构开发跨终端应用（大屏端、PC端、移动端），实现权限控制、告警管理、API服务；\n2、提供图形化、拖拽式操作界面，支持业务逻辑数字化配置。\n\n五、统一在线监测应用\n1、实现实时监测、报警中心、告警定位与视频联动；\n2、开发历史报警数据管理与闭环处理功能；\n3、负责数据可视化（设备运行统计、报警趋势、报警类型占比、区域排行等）。\n\n\n任职要求\n\n一、学历背景\n1、本科及以上学历，计算机、软件工程、物联网工程、自动化或相关专业。\n\n二、技术能力\n1、精通 Java / Go / Python 等后端语言，熟悉 Spring Boot / 微服务架构；\n2、熟悉 Vue / React / Angular 等前端框架，能独立开发跨终端应用；\n3、熟悉 MQTT、Modbus、BACnet、OPC UA等物联网通讯协议；\n4、有视频流处理（FFmpeg/HLS/RTMP/FLV）开发经验；\n5、熟悉 MySQL / PostgreSQL / Redis / Kafka / RabbitMQ 等常见数据库和中间件；\n6、了解三维可视化（Cesium、Three.js、WebGL、数字孪生平台对接）技术；\n7、有设备报警、规则引擎、实时数据采集与处理经验。\n\n三、优先条件\n1、有电力/能源/智慧园区/智慧建筑 相关系统研发经验者优先；\n2、熟悉 Docker / K8s / 私有化部署，有大规模系统上线经验；\n3、有边缘计算设备（如树莓派、工控机、国产网关）开发经验者优先。', '五险一金,年终奖金,补充医疗保险,带薪年假,做五休二', '0');
INSERT INTO `t_job_temp` VALUES ('瑞芯微电子股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1291/1290776/1290776_300.png?637235176253118983', '电子技术/半导体/集成电路', '1000-5000人', '机器学习平台工程师-福州 (MJ000457)', '全职', '1年及以上', 15000, 30000, '本科', '岗位职责：\n1、 负责机器学习平台设计，包括框架及应用层接口、底层运算性能优化、硬件调度、平台端工具等；\n2、 负责机器学习算法评估、设计及产品化；\n岗位要求：\n1、 本科及以上学历，计算机，信号系统，自动化、软件工程、电子、通信、物理、数学等相关专业；\n2、 熟练掌握C/C++及Python，熟悉Linux基本操作；\n3、 具备机器学习相关知识，掌握机器学习常用算法原理及工程实现方法；\n4、 必须具备机器学习或深度学习框架（如TensorFlow/MxNet/Caffe）使用经验；\n5、 掌握计算机视觉、图像处理、信号处理等相关领域基础知识；\n6、 良好的专业英文文献阅读和资料搜索能力；\n7、 有实际项目经验优先或有相关论文、专利、比赛获奖者优先。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建罗德数字科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9465/9464040/44840499817179881728_300.png?1742544193688', '计算机软件', '1000-5000人', '数据分析工程师（福州）', '全职', '3-5年', 8000, 13000, '本科', '岗位：数据分析工程师\n岗位职责67\n1、负责电力负荷、电量等时序数据的清洗与基础分析，支持业务部门的数据查询与报告生成需求。使用统计方法（如趋势分析、波动规律挖掘）描述数据特征，辅助业务决策。\n2、基于6767阿里云数据中台6767（MaxCompute、DataWorks等）搭建数据存储与处理流程，实现数据标准化处理与特征提取。\n3、加分项：在团队指导下参与基础预测模型的调优与效果监控，参与模型调整与部署。\n任职要求\n1、本科及以上学历6767，计算机、统计学、电力工程、数学或相关专业。\n2、技能要求：熟练使用SQL，能独立完成复杂查询、数据聚合及多表关联操作。熟悉Python基础6767：掌握Pandas、NumPy等库进行数据清洗与处理。\n3、能独立完成数据质量校验、异常值处理及基础统计报告输出。\n4、具备时序数据处理（如负荷、电量数据）或电力行业数据背景者优先。熟悉阿里云平台6767，了解阿里云数据中台基础操作（数据同步、调度任务配置）优先。\n5、工作细致严谨，确保数据准确性与交付时效。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建顶点软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1546/1545107/1545107_120.gif?636501560681636985', '计算机软件', '1000-5000人', 'C++开发工程师(TLA01E01)', '全职', '1年及以上', 9000, 18000, '本科', '工作职责：\n交易类产品代码开发\n\n任职要求：\n1、具有大学本科及以上学历、计算机相关专业毕业；\n2、具备扎实的C/C++编程基础，并有一年及以上的实际项目开发经验，能够熟练运用C/C++语言进行高效、稳定的软件开发；\n3、熟悉Linux操作系统环境及TCP/IP网络协议栈，能够独立完成基于Linux的软件开发与部署；\n4、对MySQL、Oracle等主流数据库有深入了解，能够熟练运用并进行应用开发、优化及维护；\n5、具备较强的逻辑思维能力，能够对复杂问题进行分析并提出解决方案；具备持续学习能力，能够快速适应新技术、新工具，保持技术竞争力；\n6、具备良好的团队合作精神，注重与团队成员的紧密协作；具备高度的责任心，确保高质量、高效率地完成工作。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('北京骐骥优才科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/11/10051/10050331/188104478846297813415_300.png?1771992008596', '专业服务(咨询、人力资源、财会)', '150-500人', '物联网工程师（初级/中级）', '全职', '1年及以上', 7000, 11000, '本科', '【工作内容】\n- 参与物联网系统的设计、开发与调试，协助完成设备接入与数据采集；\n- 负责物联网平台的维护与优化，提升系统稳定性与性能；\n- 配合团队进行产品测试与问题排查，确保项目顺利推进；\n- 协助撰写技术文档及用户手册，支持项目交付与后期运维。\n【任职要求】\n- 本科学历，计算机、电子类、自动化、通信类等相关专业；\n- 熟悉C/C++、Python等编程语言，了解TCP/IP、MQTT等通信协议；\n- 对物联网架构有一定了解，具备良好的学习能力和团队协作精神；。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('北京先进数通信息技术股份公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/1/106/105547/105547_120.gif?635762665713877419', '计算机软件', '1000-5000人', 'AI应用研发工程师（福州）(J14974)', '全职', '5年及以上', 12000, 20000, '本科', '工作职责:\n1.负责AI应用成果转化，与业务专家合作，了解业务产品需求并转化为大模型应用方案，主导相关应用的开发实施，负责大模型业务场景应用落地端到端工作；02\n2.基于大语言模型、多模态等技术方法，实现金融领域下游任务场景的落地应用，包括对话机器人、坐席助手、文本生成、阅读理解、数据分析等；\n3.02负责金融领域具体业务场景的开发，包括：提示词工程、增强检索和智能体工作流构建等，负责应用工程优化和效果调优；\n4.02跟踪并分析行业应用动态，持续优化和改进现有业务解决方案；并梳理典型案例进行业务应用推广。\n\n任职资格:\n1.学历背景：计算机、人工智能、数学相关专业本科及以上学历；67\n2.工作经验：5年工作经验，2 年以上AI工作经验，大数据领域相关工作经验优先；\n3.编程能力：熟练掌握 Java、Python 编程开发语言，具备扎实的编程功底与良好编码习惯；67\n4.核心技术：掌握 Prompt、RAG、Agent 的基本原理与应用方法，熟悉 LangChain 等应用范式；\n5.应用能力：熟悉大模型主流应用范式（知识问答、文本理解、文档生成、智能调度、AIGC 交互式对话产品研发等）；\n6.基础能力：具备扎实的计算机基础，深入理解数据结构与算法，精通关系型数据库设计及 SQL，精通 Linux 操作系统，具备分布式、多线程及高并发系统开发经验与性能调优能力；67\n7.有大模型多机多卡训练、部署、服务化及加速技术能力或具备深度学习、NLP 算法、模型微调、强化学习基础知识，熟悉业界主流大语言模型算法原理及 SFT、RLHF 等训练（包括二次训练、指令微调、强化学习、模型质量评估、模型加速）方式的优先。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '数据应用研发工程师', '全职', '2年及以上', NULL, NULL, '本科', '岗位职责：\n（1）负责兴业银行大数据应用服务的研发工作，进行数据服务方案设计、开发及上线后运营维护；\n（2）根据应用情况和研究情况进行提炼优化，形成稳定可复用的数据服务产品。\n岗位要求：\n（1）精通Python/Scala/Java等至少一种编程语言，能够针对大数据环境进行高效编程；\n（2）熟练使用Hadoop生态体系中的核心组件，能够进行集群部署、配置和优化；掌握Mapreduce、Spark批处理框架；掌握Storm/Flink/Spark Streaming等至少一个流处理框架，能够实现实时或准实时数据流处理。\n工作地点：上海', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('深圳市锐科信息技术有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2188/2187692/2187692_120.gif?636068706978668270', '计算机服务(系统、数据服务、维修)', '1000-5000人', 'PAAS工程师', '全职', '3年及以上', 15000, 17000, '本科', '1、本科及以上，3年及以上运维工作经验，2年商业开发经验;\n2、熟练掌握Linux、shell开发、网络排错命令;\n3、熟恶云原生、中间件、Java商用软件开发。\n4、熟恶CCE、ROMAConnect、DCS产品功能及组件功能;5、掌握高阶服务安装部署方法，具备独立定位安装部署中的问题。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建汉特云智能科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/6/5559/5558065/5558065_300.png?637011148396747261', '互联网/电子商务', '50-150人', '软件开发工程师', '全职', '3-5年', 10000, 15000, '本科', '岗位职责：\n1、负责机器人3D运维工具及仿真软件开发与维护；\n2、负责需求分析、技术方案设计及软件架构搭建等；\n3、负责工具的使用说明及开发文档编写；\n4、负责对标机器人相关工具或软件；\n5、关注图形与点云处理方面的新技术，进行技术预研和技术评估；\n岗位要求：\n1、本科及数学，计算机、信息类相关专业；\n2、具有3D点云数据处理、仿真软件2年以上开发经验；\n3、基于QT、VS开发平台软件开发经验；\n4、熟练掌握PCL、OpenGL-3D等点云处理库，具备3D图形学和相关数学知识；\n5、熟练使用C++、Python、Java等开发语言；\n6、有机器人室外3D工具开发者优先；\n7、具备较强的问题分析和定位能力，能够独立思考和解决测试过程中遇到的问题；\n8、具有较强的责任心及有良好的沟通能力、团队协作能力和抗压能力；', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建海创光电技术股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2910/2909367/2909367_120.gif?636386494715530739', '通信/电信/网络设备', '1000-5000人', 'AI工程师', '全职', '3年及以上', 7000, 11000, '本科', '工作内容：\n1、与内部各业务部门（如行政、财务、人力、销售、运营等）紧密合作，深入挖掘和分析办公场景中的痛点、低效环节和自动化需求；\n2、针对识别出的需求，设计可行、高效且具有前瞻性的AI技术解决方案，并完成技术选型与架构设计；\n3、将开发的AI应用与公司现有系统OA进行无缝集成，并负责应用的部署、运维和监控；\n4、持续跟踪已上线应用的效果，收集用户反馈，基于数据不断迭代和优化模型及产品功能；\n5、在内部分享AI技术趋势和***实践，赋能业务人员使用AI工具，提升整个组织的AI应用水平；\n岗位要求：\n1、本科及以上学历，软件、计算机、数学、人工智能等相关专业，有3年以上相关岗位工作经验；\n2、熟悉机器学习常用算法（如分类、回归、聚类）和深度学习基础（如CNN, RNN, Transformer），具有大语言模型（LLM）的实际应用经验，熟悉至少一种主流LLM API（如 OpenAI GPT, 文心一言, 通义千问, Kimi, DeepSeek等）的调用和集成；\n3、了解提示工程（Prompt Engineering）技巧，能高效地设计和优化提示词；\n4、熟悉常见的LangChain、LlamaIndex等AI应用开发框架；', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('广州南天电脑系统有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2722/2721234/2721234_120.gif?636135918633925671', '计算机软件', '500-1000人', '自动化测试工程师', '全职', '2年及以上', 9000, 12000, '本科', '岗位要求\n1、熟练掌握Python或Java编程语言，具备良好的代码风格和变成习惯，具备相关项目经验（开发、测试开发、自动化测试）；\n2、具备自动化测试框架/工具平台设计及开发能力；\n3、能掌握一种开发框架，如springboot或flask等，熟练使用git版本管理；\n4、逻辑清晰、沟通顺畅、具体团队合作经验；\n5、加分项：面向对象、设计模型、pandas、numpy数据处理、devops流水线、javascript、测试开发经验；\n6、学信网可查本科学历，熟悉银行业务知识，有金融项目测试经验优先。', '五险一金,定期体检,员工旅游,带薪年假,节日福利,周末双休', '0');
INSERT INTO `t_job_temp` VALUES ('福州买购软件科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/8/7594/7593304/47435868727055367729_300.png?1758789672815', '计算机软件', '少于50人', 'AI工程师', '全职', '1年及以上', 12000, 20000, '本科', '【工作内容】\n1. 负责人工智能算法的设计、开发和优化，推动AI解决方案在实际业务场景中的应用；\n2. 负责机器学习模型的训练、调优及部署，提升智能化水平；\n3. 对接相关业务部门，结合实际业务应用场景，分析业务需求，提供AI解决方案；\n【任职要求】\n1. 本科及以上学历，数学、计算机等相关专业背景；\n2. 精通Python等至少一种编程语言，具备良好的数据结构、算法分析与设计基础；\n3. 对人工智能领域有浓厚兴趣，具备良好的沟通能力、团队协作能力和学习能力；\n4. 至少一个大型AI项目开发经验。', '五险一金,年终奖金,周末双休', '0');
INSERT INTO `t_job_temp` VALUES ('闽都创新实验室', 'https://img01.51jobcdn.com/fansImg/CompLogo/7/6695/6694928/1650247455837_300.jpeg?1650247634691', '学术/科研', '150-500人', '雷达数据处理算法工程师', '全职', '2年及以上', 16000, 25000, '硕士', '岗位职责：\n\n1、多模态智能感知算法软件设计：设计并实现以雷达为核心的多传感器智能感知软件方案。将雷达数据与气象水文数据、视觉图像、IMU等异构数据进行有效对齐与融合，构建统一的环境感知模型，设计智能感知等软件；\n\n2、雷达智能算法开发与优化：负责雷达数据处理链路的算法设计、仿真与优化，包括但不限于目标智能识别与跟踪。重点探索并应用深度学习等AI技术，直接从雷达数据中实现目标智能检测识别，提升系统在强杂波、干扰下的探测性能，具体任务包括模型剪枝、量化、推理加速。\n\n3、参与数据实测、开展性能分析，进行理论设计与实测性能的比对验证，输出设计改进建议报告；\n\n4、协调硬件、算法及软件部门，共同完成系统性能评估与应用效果论证。\n\n任职资格：\n\n1、硕士及以上学历，数学、物理学、计算机科学与技术、电子信息工程、电子科学与技术、信号与信息处理等相关专业，具有应用机器学习等人工智能方法解决实际数据分析问题的经验者优先；\n\n2、熟悉软件应用设计，熟练掌握Python、Matlab等建模、仿真与数据分析工具，具备良好的C/C++编程能力；\n\n3、具备扎实的数理统计与信号处理基础，对数据敏感，具备从数据中分析问题、发现规律的能力，能独立设计并实现数据处理逻辑与算法；\n\n4、优秀的学习能力、主动性与责任心，良好的沟通协调能力与团队合作精神，抗压能力强。', '五险一金,绩效奖金', '0');
INSERT INTO `t_job_temp` VALUES ('微创（上海）网络技术有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/6/5691/5690803/5690803_300.png?637079585582350535', '计算机软件', NULL, '中级软件测试', '全职', '1年及以上', 7000, 9000, '本科', '岗位职责：\n1、负责全软件产品功能测试用例手工执行；\n2、负责第三方对接平台的准出测试;\n3、防火墙设备简单功能测试等;\n任职要求：\n1、测试技能:1年以软件测试执行经验，会熟练使用抓包工具，例如wireshark等；\n2、网络知识:1年网络或软件产品测试经验，了解基本网络L2或L3基础原理；\n3、开发技能:掌握Python开发语言或熟悉RF自动化框架，能够独立开发测试脚本；\n4、学历要求:本科及以上学历，计算机、通信、电子及相关专业；\n5、其他要求:了解软件开发测试流程;熟悉Linux操作系统基本操作;有软件产品相关测试或交换机基础配置、服务器搭建经验等。', '五险一金,专业培训,周末双休', '0');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '功能测试工程师', '全职', '无需经验', NULL, NULL, '本科', '1、负责软件测试的组织管理、测试设计、测试执行；\n2、负责测试技术研究。\n\n1、具备测试组织实施、测试需求分析、测试架构设计、测试执行等能力；\n2、熟悉CICS、WebLogic、Apache、Tomcat、Tuxedo、JBoss、WebSphere等至少一种中间件技术；\n4、熟悉AIX、Unix、Linux、Windows等至少一种操作系统的管理；\n5、熟悉Oracle、Informix、MySQL等至少一种数据库技术；\n6、熟练掌握JAVA、C、Python等至少一门编程语言；\n7、具有金融IT相关领域大中型项目开发测试经验者优先考虑；\n8、具有良好的职业道德，遵纪守法，品行端正，过往无不良记录，身心健康，有进取精神，有良好的沟通协作能力和团队意识，能够承担工作压力。\n\n注：有金融业务经验的优先，包括但不限于零售金融，企业金融，同业金融等业务经验。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('上海惠程信息科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/6/5332/5331392/248509448584196965208_300.png?1679298327259', '汽车', '50-150人', 'CAE软件高级应用开发', '全职', '无需经验', NULL, NULL, '本科', '岗位职责:\n1. 基于HyperWorks进行前后处理二次开发；\n2. 使用Tcl/TK、Python构建用户界面和代码逻辑；\n3. 参与用户需求收集、整理和撰写用例。\n\n岗位要求：\n1. 理工科，本科及以上学历，有力学背景或CAE仿真经验；\n2. 有编程基础（Tcl/TK、C语言或Python）；\n3. 有使用HyperWorks软件或仿真分析经验者优先；\n4. 逻辑思维能力强，具有独立工作能力和团队协作精神；\n5. 具有强烈的责任感，工作积极主动；\n6. 具有良好IT方面知识者优先（如操作系统，网络，数据库等）。', '年终奖金,股票期权,员工旅游,五险一金,餐饮补贴,专业培训,出国机会', '0');
INSERT INTO `t_job_temp` VALUES ('福建汉特云智能科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/6/5559/5558065/5558065_300.png?637011148396747261', '互联网/电子商务', '50-150人', '开发助理工程师', '全职', '1-3年', 6000, 9000, '本科', '工作职责：\n1.负责基础软件研发、文档编写、内部测试、环境部署及系统维护\n2.负责项目对接联络及项目进度跟进\n\n岗位要求：\n1.熟悉java、C++、python等编程语言\n2.善于动手实践、喜好专研，能主动学习与工作相关的知识和技术\n3.沟通、表达及组织能力好', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('微创（上海）网络技术有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/6/5691/5690803/5690803_300.png?637079585582350535', '计算机软件', NULL, '中级java开发', '全职', '3年及以上', 8000, 12000, '本科', '岗位职责：\n1、负责参与软件产品的需求分析、设计、编码、测试和维护等工作。\n2、能够进行后端的开发，包括服务器端逻辑处理，数据库设计等。\n3、与团队成员紧密协作，确保项目的顺利进行，解决开发过程中遇到的问题。\n4、能够编写清晰的详细设计文档等。\n任职要求：\n1、本科及以上学历，精通JAVA语言，具有3年以上java项目开发工作经验；\n2、熟悉Java软件体系架构、设计模式，能够熟悉使用IDEA等开发工具及Spring、Spring Boot、MyBatis等框架进行开发；\n3、熟练使用各主流数据库，如MySQL、redis缓存技术等；\n4、熟悉Linux基本命令，有Linux环境Docker部署及维护经验；有Docker容器技术；\n5、熟悉Python语言，有过Python项目经验的优先；\n6、具有良好的团队协作精神和沟通能力。', '五险一金', '0');
INSERT INTO `t_job_temp` VALUES ('闽都创新实验室', 'https://img01.51jobcdn.com/fansImg/CompLogo/7/6695/6694928/1650247455837_300.jpeg?1650247634691', '学术/科研', '150-500人', '雷达软件工程师', '全职', '3年及以上', 16000, 26000, '硕士', '岗位职责：\n\n1、雷达嵌入式软件驱动设计部署与性能攻坚：AI算法和传统算法在嵌入式平台（如RK3588）上的驱动移植、优化与部署工作。以及高性能C++驱动与应用代码，确保算法软件在资源受限的边缘设备上满足实时性要求；\n2、参与数据实测、开展性能分析，进行理论设计与实测性能的比对验证，输出设计改进建议报告；\n\n3、协调硬件、算法及软件部门，共同完成系统性能评估与应用效果论证。\n\n任职资格;\n\n1、硕士及以上学历，数学、物理学、计算机科学与技术、电子信息工程、电子科学与技术、信号与信息处理等相关专业；\n2、熟悉RK3588与Linux开发环境，驱动编写，软件应用设计，熟练掌握Python、Matlab等建模、仿真与数据分析工具，具备良好的C/C++/C#编程能力；\n\n3、优秀的学习能力、主动性与责任心，良好的沟通协调能力与团队合作精神，抗压能力强。', '五险一金,绩效奖金', '0');
INSERT INTO `t_job_temp` VALUES ('瑞芯微电子股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1291/1290776/1290776_300.png?637235176253118983', '电子技术/半导体/集成电路', '1000-5000人', 'ISP图像算法工程师-福州 (MJ000503)', '全职', '1年及以上', 20000, 38000, '本科', '岗位职责：\n1、	聚焦传统 ISP 及 AI - ISP 核心算法，深入开展ISP核心模块的算法设计工作，基于公司芯片平***成算法实现，并持续优化改进，提升图像质量与处理效率。\n2、	与内部团队协作，推动算法在不同平台的硬件移植与验证，优化功耗、内存占用及芯片资源利用率；\n3、	跟踪行业前沿，开展影像算法前瞻性研究。\n职位要求：\n1、	本科及以上学历，物理、数学、计算机、电子信息、信号处理、自动化、通信工程、光学工程等相关专业，具备扎实的专业理论基础；\n2、	5 年以上 ISP 算法开发经验，具备多个 ISP 核心算法开发经验。熟悉 ISP Pipeline，了解 ISP 架构，对图像质量有深入认识；\n3、	熟练运用 C、C++、Python等编程语言进行算法开发与验证；具备扎实的图像处理理论知识，熟悉各类常用图像处理方法。\n4、	具备优秀的跨团队沟通能力、问题分析解决能力，能适应技术文档撰写与英文技术资料阅读； \n5、	具有良好的责任心与沟通能力。\n工作地点：福州/上海', '五险一金,员工旅游,定期体检,专业培训,出国机会,年终奖金,绩效奖金', '0');
INSERT INTO `t_job_temp` VALUES ('福建邮通技术股份有限公司', 'https://img04.51jobcdn.com/im/mkt/app/51job_phone/app/homelogo/new/home_logo_default_imnetwork.png?version=20241112', '通信/电信/网络设备', '500-1000人', '软件开发', '全职', '无需经验', 3000, 6000, '大专', '【工作内容】\n- 负责公司各类软件系统的开发与维护，包括前端、后端及数据库模块的设计与实现；\n- 参与需求分析、系统设计、代码编写、测试及部署等全流程开发工作；\n- 与产品、测试及运维团队紧密协作，确保项目按时高质量交付；\n- 持续优化系统性能，提升用户体验和系统稳定性；\n- 编写技术文档，协助团队成员进行知识共享与技术交流；\n- 根据业务需求，灵活运用Java、Python、C等编程语言进行功能实现。\n【任职要求】\n- 熟练掌握Java、C、Python等编程语言，具备良好的编码习惯和逻辑思维能力；\n- 熟悉MySQL、MongoDB等数据库技术，能够独立完成数据模型设计与SQL语句编写；\n- 熟悉Eclipse、Visual Studio等开发工具的使用，具备良好的开发环境配置能力；\n- 了解操作系统原理及网络协议，具备基本的系统调试与问题排查能力；\n- 具备良好的分析、设计和编码能力，能够独立完成模块开发任务；\n- 具有较强的沟通、协调和团队合作能力，能够适应快节奏的工作环境；\n- 具有较强的学习能力和自我驱动力，能够快速掌握新技术并应用到实际工作中；\n- 具备高度的责任心和工作积极性，能够主动承担工作任务并保证质量；\n- 熟悉敏捷开发流程，具备一定的项目管理经验者优先考虑；\n- 学历要求为大专及以上，年龄不限，无需相关工作经验。\n【薪酬福利】\n- 提供具有竞争力的薪资待遇，具体面议； \n- 享受五险一金、带薪年假、节日福利等完善的员工保障体系； \n- 提供良好的职业发展空间和培训机会，助力个人成长。', '带薪年假,通讯补贴,补充医疗保险,补充公积金,绩效奖金,年终奖金', '0');
INSERT INTO `t_job_temp` VALUES ('前锦网络信息技术（上海）有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/9/8943/8942798/167332862891016813763_300.png?1770087169753', '专业服务(咨询、人力资源、财会)', '5000-10000人', '自动化软件工程师', '全职', '2年及以上', 10000, 17000, '本科', '岗位职责：\n1、负责基于 LabVIEW 平台的工业自动化系统开发与维护，完成自动化设备控制逻辑编程及\n位机设计，并对现有软件进行维护和优化。\n2、参与生产需求分析和方案设计，编写技术方案并实现运动控制器/伺服器/驱动器等硬件集\n成调试及测试。\n3、配合团队进行设备上位机软件和其它软件的异常处理，优化系统运行效率及稳定性。\n4、编写技术文档并协助解决现场应用中的软硬件联调问题。\n5、持续跟踪行业新技术趋势，推动现有系统的迭代升级。\n岗位要求：\n1、本科及以上学历，测控技术与仪器、自动化、电子信息工程或相关专业优先；\n2、熟练掌握 LabVIEW 编程语言，了解常用 LV 框架，具备独立开发复杂控制系统的能力，有\n2 年及以上 LabVIEW 开发经验；\n3、熟悉常用的通讯协议，如 RS232/GPIB/TCP/MODBUS 等；熟悉 Sql 常用语句及常用数据操\n作，熟悉 NI Vision，掌握 C#/Python，能快速适配多语言环境；\n4、具备良好的逻辑思维能力与跨部门协作意识，能解决生产过程中的突发问题，具有较强的\n责任心，对工作认真负责。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('扬腾创新（福建）信息科技股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/7/6648/6647804/6647804_300.png?637613399617858430', '计算机软件', NULL, '产品运营(J12273)', '全职', '1年及以上', 8000, 16000, '本科', '工作职责:\n1、店铺全面运营：负责平台店铺的日常运营、产品上架、优化与维护，确保店铺健康运营；\n2、产品管理与优化：负责汽配产品的Listing创建与深度优化，包括标题、关键词、描述、图片及视频，提升产品曝光与转化；\n3、数据驱动销售：分析销售数据、平台报告及市场趋势，制定并执行营销策略（如促销活动、广告投放），完成销售目标；\n3、库存与供应链协同：监控库存状况，与采购、供应链团队紧密协作，优化库存周转，避免断货与滞销；\n4、客户与市场洞察：处理客户咨询与售后，收集市场与竞品信息，为产品开发与营销策略提供建议。\n\n\n\n任职资格:\n1、本科及以上学历，理工科专业优先，英语六级及以上，有汽配垂直平台实操经验者优先；\n2、出色的学习能力、责任心强，能高效处理重复性工作并保证准确性，良好的沟通协调能力和团队合作精神；\n3、做事耐心细致，上进、积极创新、有拼劲冲劲，抗压能力强；\n4、具备优秀的信息提炼、文案撰写和编辑能力，对细节有极致关注；\n5、具备基本的数据敏感度，能使用Excel进行基础数据分析。\n\n加分项：\n1、英语口语或日语优秀；\n2、熟练使用办公软件（Word/PPT/Excel）,基础掌握Python数据技能；\n3、了解汽配类产品基础知识，或对汽配、汽车后市场有浓厚兴趣优先。', '年终奖金,定期体检,专业培训,带薪年假,节日福利', '0');
INSERT INTO `t_job_temp` VALUES ('中国平安财产保险股份有限公司福建分公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2013/2012172/2012172_300.jpg?637447661494861322', '保险', '1000-5000人', '数据运营岗', '全职', '1年及以上', 7000, 10000, '本科', '岗位职责：\n1、基础数据建设，底层数据挖掘，自动化报表搭建；\n2、预实调度管理，市场信息收集分析；\n3、机构、渠道团财意业务经营推动及问题剖析，预警并督导问题指标改善；\n4、领导交办的其它工作。\n\n岗位要求：\n1、学历专业：大学本科及以上学历 ；\n2、专业能力：有较丰富的推动或销售经验，能独立制定个性化产品策略、销售策略和核保策略优先；\n3、专业方向：数统、计算机等相关专业优先。\n\n福利待遇：\n1.工资构成：基本工资+绩效工资+年终奖；\n2. 现金福利：节日费、生日费、取暖/降温费等；\n3. 社会保险：养老保险、医疗保险、失业保险、生育保险、工伤保险、住房公积金；\n4. 补充保险：员工综合保障计划、企业年金计划；\n5. 休假：年休假、特殊岗位考试假、妇女节等；义务献血假、婚假、产假、哺乳假等。', '年终奖,周末双休', '0');
INSERT INTO `t_job_temp` VALUES ('福建海创光电技术股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2910/2909367/2909367_120.gif?636386494715530739', '通信/电信/网络设备', '1000-5000人', '制造软件工程师', '全职', '无需经验', 6000, 10000, '本科', '工作内容\n1、负责生产测试性软件的开发与维护；\n 2、搭建生产需求的各种光学检测平台，并应用软件实现数字化和自动化检测；\n 3、根据生产需要主导自动化系统方案设计、规划和实施；\n 4、配合设计、自制各类非标自动化加工设备；\n 岗位要求\n 1.本科学历，计算机、软件、电子等专业； \n2. 深入理解机器视觉原理、图像处理算法（如滤波、分割、形态学、特征提取）和模式识别技术； \n3.熟练掌握至少一种主流视觉软件平台（如 Halcon, OpenCV）的开发和应用； \n4.具备设计、选型、调试工业相机、镜头、光源系统的能力，解决成像质量问题； \n5.精通至少一门高级编程语言（如 C++, C#, Python）用于开发视觉算法模块、上位机软件或与设备接口； \n6. 熟识主流数据库中的一种或多种,如MYSQL、SQLite、SqlServer；', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福耀玻璃工业集团股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1520/1519638/1519638_120.gif?635700459975788354', '机械/设备/重工', '10000人以上', '机器人应用工程师', '全职', '3年及以上', 10000, 15000, '本科', '岗位职责：\n1.负责智能机器人应用落地工作，协调内外部资源，推动研发项目落地；\n2.负责智能机器人SDK二次开发；\n3.负责视觉等上位机程序的开发；\n4.参与机器人工业模型部署；\n5.编写软件开发文档及其他相关的文件工作。\n\n岗位要求：\n1.本科及以上学历，自动化、机器人、计算机、电子、控制等相关专业；\n2.3年以上机器人、视觉相关应用或研发经验；\n3.有项目管理潜力；\n4.掌握至少1种机器人的应用编程，具有机器人研发经验优先；\n5.掌握OpenCV、HALCON等视觉库，具备图像处理、目标检测、识别与定位能力；\n6.掌握 C++，c 或 Python；\n7.掌握ROS/ROS2框架，能独立开发功能包，熟悉Linux环境；\n8.了解SLAM路径规划、避障算法等优先；\n9.了解熟练使用仿真工具（如Gazebo、RobotStudio、FlexivStudio等）进行虚拟调试与验证，有成功项目案例者优先；\n10.了解常用算法（如路径规划A*、D*、RRT等）、数据结构，能高效实现复杂功能。理解正/逆运动学（FK/IK）、动力学建模、轨迹规划。\n\n工作地点：福建省福州市福清市福耀集团总部', '五险一金,年终奖金,定期体检,餐饮补贴,节日福利,免费班车,周末双休', '0');
INSERT INTO `t_job_temp` VALUES ('凹凸电子（深圳）有限公司', 'https://img04.51jobcdn.com/im/mkt/app/51job_phone/app/homelogo/new/home_logo_default_elect.png?version=20241112', '电子技术/半导体/集成电路', '150-500人', '软件工程师', '全职', '无需经验', 4000, 5000, '本科', '工作地点为福建平潭！平潭！平潭！\n应届生只接受2025年毕业。\n职位描述：\n1.	负责基于SOC芯片的固件开发和维护；\n2.	负责芯片linux驱动开发和维护。\n3.	负责PC端工具和手机端App开发和维护。\n4. 配合部门同事解决客户端反馈的问题。\n5. 具备良好的文档能力，能够按照要求编写软件开发文档。\n\n任职要求：\n1. 本科及以上学历，软件，计算机和电子相关专业，应届生。\n2. 有驱动，嵌入式或者上位机开发经验优先。\n3. 熟悉 C或者C++编程语言中至少一种；\n4. 熟悉软件开发流程以及软件设计文档开发工作；\n5. 良好的沟通能力；\n5. 有较强的工作责任心和团队合作意识，有一定的抗压能力。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('志豪微电子（厦门）有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9980/9979906/81047183804582241140_300.png?1758783244493', '电子技术/半导体/集成电路', NULL, '软件测试工程师/接受无经验', '全职', '无需经验', 8000, 12000, '大专', '【工作内容】\n- 负责公司各类软件产品的功能、性能及兼容性测试，确保产品质量；\n- 编写和执行测试用例，跟踪并推动问题修复；\n- 参与需求评审，从测试角度提出建议，优化产品设计；\n- 协助开发团队进行自动化测试框架的搭建与维护。\n【任职要求】\n- 大专及以上学历，计算机相关专业优先；\n- 对软件测试流程有基本了解，具备良好的逻辑思维能力；\n- 具备较强的责任心和沟通能力，能够适应团队协作；\n- 有相关实习或项目经验者优先，不限工作经验。', '五险一金,年终奖金,绩效奖金,带薪年假,周末双休,做五休二', '0');
INSERT INTO `t_job_temp` VALUES ('福建海创光电技术股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2910/2909367/2909367_120.gif?636386494715530739', '通信/电信/网络设备', '1000-5000人', '视觉工程师', '全职', '5年及以上', 8000, 12000, '本科', '1、负责在自动化设备方案设计阶段，根据项目要求，设计视觉解决方案；\n2、负责光源的选型：根据项目检测需求进行光源的选型和测试，并输出测试报告；\n3、负责按项目需求，完成自动化设备视觉系统的程序编写、调试、验证、归档、验收及问题点对策优化等工作；\n4、负责视觉系统前瞻技术的开发和实验平台搭建、测试和验证，并输出技术报告；\n岗位要求\n1、本科学历，有5年相同岗位工作经验\n2、深入理解机器视觉原理、图像处理算法（如滤波、分割、形态学、特征提取）和模式识别技术；\n3、熟练掌握至少一种主流视觉软件平台（如 Halcon, OpenCV）的开发和应用；\n4、具备设计、选型、调试工业相机、镜头、光源系统的能力，解决成像质量问题；\n5、精通至少一门高级编程语言（如 C++, C#, Python）用于开发视觉算法模块、上位机软件或与设备接口；\n6、熟识主流数据库中的一种或多种,如MYSQL、SQLite、SqlServer；', '周末双休,带薪年假,免费班车,全勤奖,节日福利,餐饮补贴,高温补贴,五险一金,专业培训,绩效奖金', '0');
INSERT INTO `t_job_temp` VALUES ('天翼视联科技股份有限公司', 'https://img04.51jobcdn.com/im/mkt/app/51job_phone/app/homelogo/home_logo_default.png?version=20241112', '通信/电信运营、增值服务', '150-500人', '全栈开发工程师（福州）', '全职', '在校生/应届生', 8000, 16000, '硕士', '学历要求\n硕士及以上学历\n\n专业要求 \n计算机、电子信息、自动化、数学、物理等相关专业\n\n岗位职责 \n1.参与公司产品全栈开发，负责前后端功能模块设计、开发与优化?\n2.参与需求评审、技术方案制定，保障项目交付质量?\n3.与多团队协作推进技术方案落地，攻克技术难题?\n4.根据需要参与国内外技术对接与系统部署?\n\n应聘资格要求 \n1.学历：硕士及以上学历，计算机相关专业优先?\n2.技术：?\n1）了解前端 Vue/React 等框架，掌握 HTML5/CSS3/JavaScript 基础?\n2）熟悉 Java/Python 等至少一门后端编程语言?\n3）掌握主流数据库基本操作?\n3.语言：英语 CET-4 及以上，具备技术文档阅读能力?\n4.特质：学习能力强，责任心强，善于沟通协作?\n\n*加分项?\n- 有开源项目经验或技术博客?\n- 熟悉微服务、云原生技术?\n- 了解 DevOps 工具链?\n- 对物联网、通信技术有研究', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('中国平安财产保险股份有限公司福建分公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2013/2012172/2012172_300.jpg?637447661494861322', '保险', '1000-5000人', '数据分析岗', '全职', '在校生/应届生', 7000, 9000, '本科', '岗位职责：\n1、理赔数据管控-车险未决管控、非车未决管控、车险异地案件追踪管控、非车异地案件的非车管控。 \n2、 数据真实性监控，数据真实性管理办法制维护等。\n3、项目推进及其他数据分析工作。\n岗位要求：\n1、本科及以上学历\n2、具有良好的沟通协调能力、较强的逻辑思维能力，责任心强，执行力高；\n3、熟练操作PPT、EXCEL等常用办公软件，具有一定数据分析能力优先。', '六险两金,定期体检,节日福利,周末双休,带薪年假,高温补贴,年终奖,补充医疗保险,员工旅游,年终奖金', '0');
INSERT INTO `t_job_temp` VALUES ('志豪微电子（厦门）有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9980/9979906/81047183804582241140_300.png?1758783244493', '电子技术/半导体/集成电路', NULL, '嵌入式硬件工程师', '全职', '无需经验', 8000, 12000, '本科', '【工作内容】\n- 参与嵌入式系统硬件方案的设计与开发，完成电路原理图和PCB设计；\n- 负责嵌入式硬件的调试、测试及优化，确保系统稳定运行；\n- 协同软件团队进行软硬件联调，解决开发过程中的技术问题；\n- 编写相关技术文档，支持产品量产和后续维护。\n【任职要求】\n- 本科及以上学历，电子工程、通信工程、自动化等相关专业；\n- 熟悉模拟/数字电路设计，具备良好的电路分析能力；\n- 熟练使用EDA工具（如Altium Designer、Cadence等）进行原理图和PCB设计；\n- 有嵌入式开发经验者优先，能独立完成硬件开发任务；\n- 具备良好的沟通能力和团队协作精神，责任心强。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('亚信科技（中国）有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/1/304/303468/303468_120.gif?635700459830394490', '计算机软件', '10000人以上', '实习软件测试工程师', '实习', '在校生/应届生', 2000, 3000, '本科', '岗位职责：\n1、负责公司产品功能、接口、兼容性等测试。\n2、负责撰写测试用例、执行测试用例、撰写测试报告、提交BUG测试报告。\n3、负责项目相关测试文档、用户手册编写工作。\n4、协助完成软件开发的测试工作。\n\n任职要求：\n1、本科及以上学历，计算机、电子、通讯等相关专业毕业。\n2、熟悉软件专业理论知识，基础扎实。\n3、至少掌握一门编程语言基础（如Java、C/C++、Python等）和关系型数据库、熟练使用Linux/Unix操作系统，能力理解代码逻辑，有助于测试脚本编写或自动化测试。\n4、做事严谨细心，思维清晰，学习能力强，责任心强，有良好的沟通能力和分析总结问题能力，并且乐于从事测试工作\n5、实习期至少6个月以上', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('苏州顺芯半导体有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2195/2194011/2194011_120.gif?636405691201321893', '电子技术/半导体/集成电路', '少于50人', '数字集成电路验证工程师（工作地：苏州)（福州）', '全职', '在校生/应届生', 15000, 23000, '硕士', '主要职责\n1.负责芯片验证， 包括模块级， 子系统级和系统级的验证工作；\n2.基于验证计划， 开发测试用例； 与设计工程师一起进行测试用例调试， 保证通过所有\n测试项目； 根据设计规格， 负责制定验证计划；\n3.使用 UVM 或 VMM 验证方法学搭建可重用性的测试平台。\n岗位要求\n1.硕士及以上学历， 电子， 计算机， 集成电路相关专业；\n2.了解数字电路验证方法和验证流程；\n3.熟练掌握常用验证语言， 如 Verilog, System Verilog, C/C++, SVA；\n4.熟练 Perl, Python, Shell 等脚本语言者优先；\n5.具有很强的分析和解决问题能力； 具有团队协作， 良好的沟通能力。', '五险一金,员工旅游,专业培训,年终奖金,定期体检', '0');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '软件测试工程师', '全职', '在校生/应届生', NULL, NULL, '本科', '软件测试工程师\n岗位职责：\n1.负责兴业银行软件产品的功能测试、性能测试；\n2.负责自动化测试工具的开发、框架设计、脚本编写与自动化测试执行，推进自动化测试体系建设；\n3.负责性能测试问题分析定位、方案设计、脚本开发与性能测试执行，协助性能问题优化与验证；\n4.协调测试过程问题解决，推进测试实施。\n岗位要求：\n1.具备全面、扎实的软件基础知识，掌握操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全等专业知识；\n2.编程基本功扎实，掌握常用算法和数据结构；\n3.熟悉java、python等编程语言，熟悉linux/windows操作系统，熟练掌握MySQL、Oracle、TXSQL、OpenGauss等数据库SQL运用；\n4.了解软件测试相关基础知识，具有自动化测试、性能测试相关实习、实践经验的优先。\n工作地点：上海、福州、成都、深圳\n\n注：有金融业务经验的优先，包括但不限于零售金融，企业金融，同业金融等业务经验。', '五险一金,补充医疗保险,补充公积金,免费班车,交通补贴,餐饮补贴,通讯补贴,专业培训,绩效奖金,年终奖金,定期体检', '0');
INSERT INTO `t_job_temp` VALUES ('福建顶点软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1546/1545107/1545107_120.gif?636501560681636985', '计算机软件', '1000-5000人', '软件研发工程师(26届)', '全职', '在校生/应届生', 8000, 14000, '本科', '岗位职责:\n负责证券、基金&amp;资管、期货、银行、信托、要素交易市场等全域金融应用产品的开发工作。\n任职资格:\n1、2026届本科及以上学历理工科专业，包括但不限于：计算机类、电子信息类、自动化类、机械类、数学和物理等；\n2、综合素质较好，思维活跃，并具备扎实的计算机基础知识；\n3、至少熟悉一种主流编程语言（如C/C++、Java、JavaScript等）和主流框架，并有一定的项目实践经验；\n4、具备MySQL或Oracle等关系型数据库的应用开发技能；\n5、具备出色的学习能力和解决问题的能力，对新技术和新业务知识充满学习热情；\n6、具备良好的沟通能力和团队协作精神，有责任心和较强的自我驱动力；\n7、热爱并致力于金融科技行业的持续发展。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建畅聊科技有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/10/9489/9488401/296250888622948772253_300.png?1743404939377', '通信/电信/网络设备', NULL, 'Java实习生', '全职', '在校生/应届生', 6000, 9000, '本科', '岗位职责：（2026届）\n1、根据任务分配，按时完成相关开发工作；\n2、在项目负责人的带领下从事软件开发、调测以及维护等工作，及时编写项目开发不同阶段的文档；\n3、协助项目相关用户手册的编写。\n岗位要求：\n1、计算机、软件工程、通信工程相关专业本科及以上学历，英语水平CET-4及以上；\n2、有项目开发经验者优先，能看懂英文文档，有良好的开发习惯和代码风格；\n3、熟练掌握Java基础知识、SpringBoot、MyBatis等Java框架；\n4、熟练掌握HTML,CSS,Javascript了解Web前端技术如vue、react，能够完成页面开发和布局；\n5、熟练掌握SQL语言，熟悉Mysql数据库，掌握redis使用。\n6、热爱编程行业，逻辑清晰，性格开朗，责任心强、工作细致，抗压能力强，善于沟通，团队协作强者优先。\n实习期间，实习补贴2500元/月，薪资范围为转正式后的薪资', '五险一金,年终奖金,餐饮补贴,交通补贴,通讯补贴,周末双休,带薪年假,节日福利', '0');
INSERT INTO `t_job_temp` VALUES ('福建博思软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/3/2902/2901331/2901331_120.gif?636124103648561544', '计算机软件', '1000-5000人', '算法工程师（知识图谱）-福州 (MJ003772)', '全职', '在校生/应届生', 17000, 22000, '硕士', '工作职责\n1、参与企业级AI平台的核心能力建设，设计并开发高可用、可扩展的大模型/Agent系统架构。\n2、负责 LLM、RAG、Agent等核心 AI 模块的工程化封装。\n3、负责知识图谱构建、实体抽取与关系推理的算法研发。\n4、探索知识图谱与LLM融合的创新方案，推动AI能力产品化落地。\n5、跟踪前沿技术动态，持续优化算法效果与工程性能。\n\n\n任职要求\n1、硕士及以上学历，计算机科学、软件工程、人工智能、数据科学等相关专业优先，必须具备知识图谱或Agent项目交付经验。\n2、精通Python编程，熟练使用主流AI框架（TensorFlow、PyTorch等），具备扎实的算法工程能力。\n3、深入理解机器学习、深度学习算法原理，熟悉Transformer、BERT、GPT等模型架构。\n4、熟悉知识图谱技术栈：Neo4j/图数据库、NER、关系抽取、知识融合，有本体建模经验优先。\n5、具备Agent系统开发经验，熟练使用LangChain、LangGraph等框架，能设计高可用、高扩展性的大模型/Agent工程架构。\n6、掌握Prompt Engineering、RAG（检索增强生成）、ToolCalling、Function Calling等AI应用关键技术。\n7、技术视野开阔，善于沟通和逻辑表达，拥有优秀的分析和解决问题的能力，良好的团队合作精神。\n8、熟练掌握 Cursor/Trae/Claude Code 等 AI 辅助开发工具，能将AI辅助融入日常开发流程。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('兴业数字金融服务（上海）股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/4/3955/3954794/3954794_120.gif?635999445609330353', '金融/投资/证券', '1000-5000人', '云原生技术专家', '全职', '2年及以上', 500000, 800000, '本科', '岗位职责：\n（1）负责兴业银行容器平台及中间件PaaS平台设计、研发、建设及维护工作；\n（2）负责容器云及中间件相关技术研究、技术标准制定、故障排查处置、安全加固等工作；\n（3）负责对使用容器云平台和接入各类PaaAAS服务系统提供技术支持。\n\n岗位要求：\n（1）熟悉Docker容器技术，深度掌握相关技术原理细节；\n（2）深度掌握Kubernetes，深度了解各资源对象、技术组件运作原理，有实际项目经验；\n（3）对应用容器化设计、改造有深度认识以及实践经验；\n（4）熟悉Linux，熟悉Python、Shell中一种脚本语言，深度理解网络原理、存储原理、虚拟化、软件定义网络SDN等；\n（5）熟悉Tomcat、Kafka、RocketMQ、Redis、Nginx等中间件中一项或者多项，具有丰富的调优、高可用架构设计、故障排查、安全加固、监控经验。\n\n符合以下一项或多项条件者优先：\n（1）曾负责或深度参与互联网或大中型金融企业的容器平台或中间件PaaS平台建设者；\n（2）具有2年以上容器平台或PaaS平台管理运维经验者；\n（3）对Docker、Kubernetes有源码级掌握者；\n（4）对云原生社区有贡献或者熟悉源码者；\n（5）具备Kubernetes Operator开发经验者；\n（6）具有Kubernetes相关认证者；\n（7）具备Redis、RocketMQ、Kafka、Zookeeper、Elastic等中间件二次开发经历者。\n工作地点：上海、成都', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建顶点软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1546/1545107/1545107_120.gif?636501560681636985', '计算机软件', '1000-5000人', '卓越研发工程师(26届)', '全职', '在校生/应届生', 10000, 20000, '本科', '岗位职责:\n负责证券、基金&amp;资管、期货、银行、信托、要素交易市场等全域金融核心应用产品的设计与开发工作。\n任职资格:\n1、2026届本科及以上学历理工科专业，包括但不限于：计算机类、电子信息类、自动化类、机械类、数学和物理等；\n2、熟练掌握至少一种主流编程语言（如C/C++、Java、JavaScript等）和主流框架，并有一定的项目实践经验、在项目中负责重要模块；\n3、对分布式系统、微服务架构、数据库原理等有深入理解；\n4、具备出色的学习能力和解决问题的能力，对新技术和新业务知识充满学习热情；\n5、具备强烈的求知欲和创新能力，能够独立思考，提出创新的解决方案；\n6、具备卓越的沟通能力和出色的团队协作精神，能够与其他团队成员有效沟通、积极协作；\n7、具备较强的自我驱动力，热爱并致力于金融科技行业的持续发展。', NULL, '0');
INSERT INTO `t_job_temp` VALUES ('福建顶点软件股份有限公司', 'https://img01.51jobcdn.com/fansImg/CompLogo/2/1546/1545107/1545107_120.gif?636501560681636985', '计算机软件', '1000-5000人', '软件测试工程师(26届)', '全职', '在校生/应届生', 7000, 12000, '本科', '岗位职责:\n1、精准设计并维护测试用例；\n2、高效执行测试与BUG追踪；\n3、撰写高质量测试报告。\n\n任职资格:\n1、2026届本科及以上学历理工科专业，包括但不限于：计算机类、电子信息类、自动化类、机械类、数学和物理等；\n2、综合素质较好，思维活跃，自我驱动力强，并具备扎实的计算机基础知识；\n3、熟悉软件测试理论、方法及流程，了解常见的测试类型（如功能测试、性能测试等）；\n4、至少掌握一种编程语言基础（如C/C++、Java、Python等）和关系型数据库，能够理解代码逻辑，有助于测试脚本编写或自动化测试；\n5、具备良好的逻辑思维能力，能够独立思考并分析测试中的问题；\n6、责任心强，具备出色的沟通能力和团队合作精神，能够积极融入团队，有效传达测试进展和问题；\n7、具备积极主动的学习态度和较强的抗压能力，愿意在快速变化的环境中不断成长；\n8、热爱并致力于金融科技行业的持续发展。', NULL, '0');
INSERT INTO `t_jobs` VALUES (24, '初级数据开发工程师', 28, '全职', '1-2年', 6000, 7000, '大专', '招聘人数： 1人\n工作地点： 福建省福州市\n用工类型： 长期员工（试用期3个月）\n薪资范围： 具体面议\n________________________________________\n核心职责 \n1.	政务数据资产目录与数据中台支持（数据资产目录、数据治理方向）\n参与政务数据资产资源目录平台的日常开发与维护，协助实现数据资源的编目、注册、发布等功能。\n支持数据中台后台数据处理流程，包括数据采集、清洗、转换、加载（ETL/ELT），保障数据的一致性和可用性。\n2.	ETL调度与数据处理\n开发、维护及优化ETL调度任务，编写和调试数据转换脚本，确保数据处理任务高效稳定运行。\n参与数据质量监控与校验，协助完成数据质量问题分析及整改方案的实施。\n3.	国产化工具与数据库适配\n使用Python及相关工具进行数据开发，适配国产数据库（如达梦、OceanBase、GaussDB、DataBend等）及大数据平台。\n参与数据治理工具（如元数据管理、数据血缘追踪）的模块开发，支持国产化替代方案的技术落地。\n________________________________________\n任职要求 \n必备技能 \n•	编程与数据处理：\n掌握Python语言，能使用国产数据库进行数据处理，具备ETL脚本开发能力。\no	熟悉SQL语法，能编写复杂查询语句并进行基本的性能优化。\n•	数据中台与工具链：\n了解ETL调度工具（如Kettle、DataX）或大数据组件（如Hadoop、Spark），有实际项目或课程经验者优先。\n具备数据治理基础知识，如元数据管理、数据质量评估等。\n•	国产化适配：\n熟悉至少一种国产数据库（如达梦、DataBend、人大金仓），具备基础开发能力。\n经验与软实力 \n•	学历经验：大专及以上学历，计算机或相关相关专业，1-2年数据开发经验（优秀应届生可放宽）。\n•	业务理解：了解政务数据治理基本概念（如数据分类分级、资产目录体系），能快速学习政务业务逻辑。\n•	综合素质：逻辑清晰，具备问题解决能力和团队协作精神，能适应政务项目的规范流程。\n________________________________________\n薪资福利 \n•	薪资结构：月薪+绩效奖金。\n•	福利保障：五险一金、带薪年假、国产化技术专项培训。\n•	试用期：3个月，薪资福利按正式标准执行。\n________________________________________\n备注说明 \n•	岗位涉及政务数据安全管理，需通过背景审查及合规培训。\n•	技术栈以Python为主，需同时支持数据中台后端处理及国产化工具链适配', '带薪年假,绩效奖金,五险一金', NULL, NULL);
INSERT INTO `t_jobs` VALUES (25, '标准管理岗', 29, '全职', '5年及以上', NULL, NULL, '本科', '岗位职责：\n1）承担或参与开发标准的立项、制修订和征集意见工作，定期对开发标准化活动领域进行梳理，开展开发标准相关子领域的标规文件制定、修订等工作；执行已发布的开发标准化相关标规文件，提出标规文件执行中的意见及建议。\n2）开展开发标准落地实施工作，负责对实施项目中开发标准的执行情况进行审核。\n3）落实开发标规文件的宣传和培训工作。\n\n任职要求：\n1、具备5年以上软件开发经验，有扎实的技术功底；\n2、具备优秀的沟通协调能力、技术理解力。\n3、具备以下一项或多项技能经验。\n （1）熟悉DevOps平台的架构设计和系统研发工作，包括但不限于代码托管、CI/CD流水线、单元测试、自动化测试、安全测试等；熟悉Jenkins、Gitlab、Artifactory、SonarQube等工具的使用。\n （2）熟悉应用开发所需工具、集成开发环境、基础框架、基础服务支撑能力等工具平台。\n （3）具备数据标准相关实施、管理经验。\n工作地点：上海、成都、福州', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (26, 'AI应用开发工程师Dify方向', 30, '全职', '2-3年', 7000, 12000, '大专', '1. 负责企业AI智能体、AI助手产品的开发、迭代与上线。\n\n2. 基于独立完成 Dify 平台对话流程、知识库、工作流配置与API发布。\n\n3. 负责接口开发、系统对接，实现低代码平台与AI系统的数据互通。\n\n4. 独立完成项目部署、测试、问题排查与维护。\n\n5. 与业务团队配合，将业务需求转化为技术实现，独立负责技术全流程。\n\n任职要求\n\n1. 大专及以上，计算机相关专业，2～3年以上实际开发经验。\n\n2. 熟练使用 Python，能独立开发接口、对接第三方系统。\n\n3. 了解大模型API调用，有AI应用落地经验。\n\n4. 能独立使用 Dify 完成AI智能体开发与部署。\n\n5. 有低代码平台（宜搭、简道云、明道云等）对接经验优先。\n\n6. 能独立负责项目，抗压能力强，沟通顺畅，责任心强。', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (27, 'Python开发（远程面试）', 31, '全职', '3年及以上', 13000, 16000, '本科', '岗位要求：\n1. 计算机科学、信息技术、统计学、数学或相关领域本科及以上学历，相关工作经验3年以上；\n2. 熟悉Pandas、NumPy、SQL，熟悉数据ETL流程与常见数据结构；\n3. 具备Python、Java、Go等编程语言经验（掌握至少两项）；\n4. 熟悉至少一种主流数据仓库技术（如Hive, Spark, Flink，Clickhouse等），对大数据处理框架（如Hadoop, Spark等）有一定了解和实践经验。\n5. 代码风格整洁，具备良好的软件工程协作能力，具备良好的沟通能力和文字撰写能力。\n6. 具备云原生知识，拥有Docker与K8S实践经验者优先。\n\n工作职责：\n1. 参与运维数据分析平台开发，负责数据指标开发与数据平台基础设施建设。\n2. 根据业务需求设计并实施数据抽取、转换、加载流程，确保数据准确性、完整性和及时性。\n3. 基于业务需求，制作各类数据报表和仪表盘，为决策提供数据支持。\n4. 参与建立并实施数据质量监控机制，定期检查数据质量，及时发现并解决问题。\n5. 协助编写技术文档，包括数据处理流程、数据字典、技术架构设计等。\n6. 参与数据项目规划、需求分析、技术选型等，探索并应用新技术，持续优化数据处理流程。', '五险一金,交通补贴,餐饮补贴,通讯补贴,定期体检', NULL, NULL);
INSERT INTO `t_jobs` VALUES (28, '大数据数据仓库开发', 32, '全职', '3年及以上', 10000, 20000, '本科', '岗位内容：\n1、负责建设数据仓库架构，包括元数据管理、ETL调度、数据集成、OLAP等子系统的设计和开发；\n2、搭建和维护数据仓库表，解决业务人员在仓库系统流程、工具使用、数据处理等遇到的问题；\n3、基于对数据的理解和业务需求，对数据进行整理、分析和挖掘。\n岗位要求：\n1、全日制本科学历，计算机、数学、统计学相关专业；3年相关经验；\n2、熟练使用SQL语言，具有2年以上数据仓库、报表系统等ETL开发、维护经验；\n3、熟悉主流的关系型数据库及MPP数据库，至少精通一门数据库，熟悉Gbase优先；\n4、熟悉Hadoop、SparK、Hive、Hbase等大数据技术者优先。', '绩效奖金,节日福利', NULL, NULL);
INSERT INTO `t_jobs` VALUES (29, '测试开发工程师', 29, '全职', '无需经验', NULL, NULL, '本科', '1、测试中台软件开发；\n2、脱敏算法、智能测试算法、数据模拟算法研究；\n3、敏感信息检测工具与平台集成开发工作。\n1、精通Java、C、PYTHON、Shell等至少两门开发语言；\n3、对数据处理或算法研究有一定经验；\n4、热爱研发工作、对工具平台建设与研究有较高兴趣。\n5、具有良好的职业道德，遵纪守法，品行端正，有进取精神，有良好的沟通协作能力和团队意识，能够承担工作压力。\n\n注：有金融业务经验的优先，包括但不限于零售金融，企业金融，同业金融等业务经验。', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (30, '奇瑞数据开发分析工程师', 33, '全职', '3-5年', 8000, 11000, '大专', '【工作内容】\n- 负责公司业务数据的采集、清洗、存储及分析，支持业务决策；\n- 参与构建数据模型和数据分析系统，提升数据处理效率；\n- 协助业务部门进行数据驱动的策略制定与优化；\n- 持续优化数据平台架构，提升数据质量与可用性。\n【任职要求】\n- 大专及以上学历，计算机、数学、统计学或相关专业优先；\n- 熟悉SQL、Python等编程语言，具备良好的逻辑思维能力；\n- 对数据挖掘、数据分析有基本了解，有相关项目经验者优先；\n- 具备良好的沟通能力和团队协作精神，责任心强。', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (31, '人工智能', 34, '全职', '2年及以上', 8000, 12000, '本科', '方向：图像检测识别、NLP、开源大模型\n\n工作内容：\n1. 负责开发图像检测、识别，大语言模型应用；\n2. 负责特定arm linux终端算力设备模型移植、测试；\n\n要求：\n1、本科及以上学历，计算机、人工智能、电子、通信等相关专业，2年及以上相关工作经验；有项目经验；\n2. 会linux操作命令，了解linux系统；\n3. 熟练使用python语言，熟练使用torch, tf等AI框架，熟练使用numpy，opencv，pandas等相关工具类库\n4. 有yolo经验，熟悉或了解大语言模型的发展趋势，熟悉agent、RAG、ollama、dify、LoRA、向量等LLM技术或平台、工具，了解AI最新发展趋势\n5. 有探索精神，做事认真负责、灵活，适应不定期加班\n\n职位福利：五险一金、带薪年假、其他商业险、餐补、年终奖金', '五险一金,年终奖金', NULL, NULL);
INSERT INTO `t_jobs` VALUES (32, '算法软件工程师', 35, '全职', '2年及以上', 12000, 20000, '硕士', '【工作内容】\n负责雷达算法信号处理和算法数据处理软件设计\n【任职要求】\n1.计算机、应用数学、信号、通信等相关专业硕士及以上；\n2.具备良好的数学基础，熟练掌握C++、Python语言及编程技巧及Matlab丁具\n3、有雷达信号处理算法、目标检测跟踪算法ARPA算法软件开发经验者优先', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (33, 'AI应用开发工程师', 36, '全职', '1年及以上', 12000, 20000, '本科', '职位描述：\n1、使用LLM（大语言模型）、向量数据库、Agent架构等AI技术栈，以及Vue、React等前端应用技术栈进行公司Agent应用构建平台的开发。\n2、快速学习并掌握前沿技术栈和技术方案，并将其应用于公司产品研发中。\n3、负责技术难点攻关和关键模块的研发，确保技术方案的可执行性和可扩展性。\n4、配合产品经理，理解并实现产品需求，确保项目的如期交付。\n5、编写高质量的技术文档和操作手册，确保团队成员的知识共享和后续维护。\n\n任职要求：\n1、计算机科学、人工智能、软件工程或相关专业本科及以上学历，优秀者可放宽要求；\n2、爱折腾、勇于挑战，具有极强的学习能力和抗压能力，能够快速适应公司的开发环境和业务需求；\n3、具备扎实的编程基础，掌握 Web前后端（如React、VUE）等技术栈；\n4、热爱编程，善于思考和解决问题，对产品质量有高度的责任心和自我要求；\n5、具有较强的团队协作能力；', '五险一金,员工旅游,绩效奖金,年终奖金,股票期权,定期体检,专业培训', NULL, NULL);
INSERT INTO `t_jobs` VALUES (34, '数据岗', 37, '全职', '无需经验', 7000, 10000, '本科', '工作职责 :\n1.基础数据建设，底层数据挖掘，自动化报表搭建；\n2.机构、渠道相关业务经营推动及问题剖析，预警并督导问题指标改善；\n3.领导交办的其它工作。\n \n\n任职资格 : \n1.本科及以上学历； 数学、统计、计算机等相关专业优先；\n2.工作严谨、认真，责任心强；\n3.具有良好的沟通协调能力、较强的逻辑思维能力，责任心强，执行力高；\n4.熟练操作PPT、EXCEL等常用办公软件，具有一定数据分析能力优先。', '五险一金,绩效奖金,年终奖金,定期体检,专业培训,带薪年假,节日福利', NULL, NULL);
INSERT INTO `t_jobs` VALUES (35, 'Python开发工程师-福州', 38, '全职', '3年及以上', 8000, 15000, '本科', '工作概述：\n1.负责AI能力模型的服务化封装；\n2.独立承担项目需求分析，完成模块设计、编码、调试以及单元测试工作，确保软件质量与性能达到预期标准；\n3.编写技术文档和维护代码库，确保代码的可读性和可维护性；\n4.参与LLM的数据清洗，数据优化工作；\n5.参与NLP相关的算法设计、模型训练、模型调优、模型部署等；\n6.参与基础NLP能力建设，如长/短文本分类、Embedding等相关技术；\n7.具备良好的团队协作精神，能够与团队成员共同解决技术难题，推动项目的顺利进行。\n\n任职要求：\n1.计算机相关专业本科及以上学历，3年以上相关工作经验；精通Python服务端开发熟练掌握numpy、pandas等数据处理框架；\n2.熟悉web开发框架（fastapi/flask/django），熟悉Linux操作系统及shell编程；\n3.熟悉mysql，redis，oracle等常用数据库，具有数据库开发和设计能力；\n4.熟悉Docker等容器类中间件，熟悉基于docker开发部署服务的流程;\n5.熟悉Linux系统，能够离线解决Linux中开发环境问题；\n6.有NLP相关AI落地项目经验者优先；\n7.有NLP大模型训练经验者优先，如BERT、 GPT等LLM等相关经验优先。', '五险一金,带薪年假', NULL, NULL);
INSERT INTO `t_jobs` VALUES (36, '金融数据开发工程师(AMB01E05)', 39, '全职', '2-5年', 8000, 16000, '本科', '岗位职责:\n1、参与项目需求分析，理解业务需求并转化为详细需求文档；\n2、在团队的指导下，用技术实现业务需求，确保代码质量符合团队标准； \n3、了解并持续学习金融工程相关知识，将原始数据转化为产品/项目需要的业务指标；\n4、负责编写相关技术文档，包含但不限于：需求、详细设计、技术方案及操作手册等，促进团队沟通与协作。\n任职要求:\n1、具有大学本科及以上学历，计算机、数学、金融工程相关专业毕业；\n2、具有2-5年软件开发相关工作经验，优秀应届毕业生亦可；\n3、熟练掌握Java或Python编程语言，以及Oracle/Mysql等关系型数据库的使用；\n4、具备出色的沟通能力和良好的团队合作精神，能够与各团队成员有效沟通，共同解决问题；\n5、具备高度责任心，对待工作严谨认真，确保任务的高质量完成；\n6、有基金/证券从业资格证或金融科技行业相关工作经历者优先。', '员工旅游,年终奖金', NULL, NULL);
INSERT INTO `t_jobs` VALUES (37, '全栈开发工程师（Python/PHP + 前端方向）', 36, '全职', '2年及以上', 8000, 16000, '本科', '岗位职责:\n\n前后端开发\n负责公司Web平台、小程序及移动端应用的全栈开发，包括需求分析、架构设计、代码实现与维护。\n使用Python/PHP完成后端业务逻辑开发。\n基于Vue.js、jQuery等框架完成前端交互开发，确保页面高效渲染与用户体验。\n\n跨平台开发\n使用UniApp框架开发多端兼容的小程序（微信、支付宝等）及APP，解决不同平台的适配与性能问题。\n熟悉微信小程序生态，包括支付、地图、授权等接口开发与维护。\n\n技术优化与协作\n优化现有系统性能，解决浏览器兼容性、数据解析效率等问题。\n配合测试团队完成功能验证，协同产品经理迭代需求，输出技术文档。\n\n任职要求\n技术能力\n后端：精通Python/PHP，熟悉FastAPI/CodeIgniter/ThinkPHP等框架，掌握MySQL/Redis数据库设计与优化。\n\n前端：扎实的HTML/CSS/JavaScript基础，熟练使用Vue全家桶（Vuex、Vue Router）、jQuery，了解Webpack/Vite等构建工具。\n跨平台：具备UniApp实战经验，熟悉小程序生命周期、原生组件封装及热更新机制。\n\n经验要求\n2年以上开发经验\n\n软性要求\n良好的代码规范、文档习惯及团队协作意识，能承受项目压力。\n对新技术敏感，主动学习前沿工具', '五险一金,员工旅游,绩效奖金,年终奖金,股票期权,定期体检,专业培训', NULL, NULL);
INSERT INTO `t_jobs` VALUES (38, '大数据开发工程师', 29, '全职', '2年及以上', NULL, NULL, '本科', '岗位职责：\n\n1、参与基于Hadoop的大数据平台的研发工作与持续优化工作。\n2、参与大数据平台的容量规划、持续交付、业务监控、应急响应，保证平台正常运行。\n3、利用大数据相关技术实现对数据的分析、挖掘、处理、及数据可视化等相关工作。\n4、学习和研究新技术以满足系统需求。\n\n岗位要求：\n\n1、拥有数据处理相关专业背景。\n2、对互联网产品有见解，关注前沿技术，有较强的学习能力、分析能力和动手能力。\n3、熟悉常用分布式计算和存储框架，如Hadoop/HDFS/Spark等。\n4、至少熟悉以下一种大数据技术组件，Hive、Impala、Hbase、Flume、Kafka、Zookeeper、Storm、Flink。熟悉资产管理、资金业务和金融工程相关领域业务者优先。\n5、个性乐观开朗，沟通能力强，具备良好的团队协作精神，能利用自身技术能力提升团队整体研发效率。\n6、多份工作经历需最近2份工作均满2年，或最近1份工作经历满3年。仅有一份工作经历的需满两年。\n工作地点：上海、成都', '五险一金', NULL, NULL);
INSERT INTO `t_jobs` VALUES (39, '数据治理岗', 40, '全职', '5年及以上', 15000, 20000, '本科', '岗位职责\n1、参与公司数据治理体系和制度流程建设工作，负责根据公司制定的数据标准，设计数据模型，推动数据管控策略实施。\n2、推动数据治理相关模块工作，包括元数据管理、数据标准管理、数据质量管理和数据资产管理等。\n3、持续推动数据治理相关系统功能完善，组织需求规划和功能验证等工作。\n4、持续引导各领域数据治理专员开展数据治理工作，推动数据资产管理和价值输出。\n5、组织开展数据治理相关宣传和培训。\n\n任职要求\n1、本科及以上学历，经济、数学、统计学，计算机学等相关专业；\n2、熟悉数据治理实施方法，至少拥有元数据管理、数据标准管理、数据质量管理和数据资产管理中1个模块的实践经验。\n3、五年以上大型金融、互联网企业的数据开发、数据管理工作经验，具有证券行业建模经验者优先。\n4、至少掌握一门常用数据处理脚本语言， 如SQL\\PYTHON，熟悉基于该语言的常用开源算法；\n5、具有较强的逻辑思维能力、数据挖掘分析能力，具备良好的敬业精神，有较强的团队协作能力、沟通能力和问题分析能力等。', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (40, 'AI 应用工程师', 41, '全职', '3年及以上', 15000, 25000, '硕士', '岗位职责：\n1、 针对光学与光机装配产品，设计可提升精度/良率的 AI 模型应用方案（含需求拆解与技术\n选型），并推动方案从原型验证到产线落地。\n2、 负责面向光学行业的 AI 模型开发，如光学缺陷识别、工艺参数优化、元件性能预测等。\n3、 根据光学数据特点进行数据预处理与特征工程，持续优化模型精度与推理效率。\n4、 贯通光学-光机组件全制造流程数据，利用数据挖掘方法释放数据价值。\n5、 跟踪前沿 AI 技术与数据挖掘工具，评估其在光学制造场景中的落地可行性。\n6、 撰写技术文档，为工程与生产团队提供技术支持。\n岗位要求：\n1、 硕士及以上学历，计算机、人工智能、数据科学、电子信息、光学工程、光电信息科学与\n工程等相关专业，博士优先。\n2、 3 年以上 AI 应用开发经验，其中至少 1 年从事光通信、激光、镜头或光学检测设备等光学\n制造相关技术岗位。\n3、 熟练使用 AI 与数据挖掘工具，了解工业云平台 AI 服务或边缘 AI 部署方案。\n4、 至少精通 Python、 Java、 C++中的一种编程语言。\n5、 熟练掌握数据挖掘方法（关联、聚类、回归、异常检测等）。\n6、 熟悉机器学习算法，了解模型微调、压缩及图像预处理技术。\n7、 熟悉大数据处理工具及数据分析库，可对光学批量数据高效清洗、转换与分析。\n8、 具备基础光学知识（几何光学、光纤、光学成像原理），了解光学制造流程，能快速理解\n现场工艺。\n9、 英语听说读写熟练。\n10、 乐于持续学习新知识、新技术与新理念。', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (41, 'AI开发工程师', 36, '全职', '无需经验', 8000, 16000, '本科', 'AI开发工程师（可应届/实习）6767\n\n参与机器学习/深度学习模型的训练、调优及部署（如NLP、CV、大模型应用）；\n使用TensorFlow/PyTorch等框架实现算法原型，并完成性能优化；\n协助将AI模型集成至产品（如API服务、智能问答系统）。\n\n参与数据清洗、标注及特征工程，构建高质量数据集；\n\n跟踪大模型（LLaMA、GPT）、Agent技术、RAG架构等方向，参与技术验证。\n\n大模型应用：微调开源模型（如Qwen）、开发RAG知识库、Agent工具链；\n垂直领域AI：结合农业、环保等行业需求开发定制化AI功能；\nAI产品辅助：参与Prompt优化、数据标注、多模态交互功能开发。\n\n技术能力\n编程基础：精通Python；\nAI框架：掌握TensorFlow/PyTorch基础，有模型训练调参经验者优先；\n工程基础：了解RESTful API、数据库（SQL/NoSQL）、Linux基础命令；\n算法理论：理解CNN/RNN/Transformer等经典模型原理', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (42, '性能测试工程师', 29, '全职', '无需经验', NULL, NULL, '本科', '1、负责金融类信息系统的性能测试和调优工作。\n2、负责性能测试需求分析、性能测试场景设计、测试数据准备、测试脚本编写和执行、性能测试数据分析和问题排查，以及性能优化建议和验证等相关工作；\n3、负责性能测试过程管理以及沟通、协调、报告编制和汇报等工作；\n4、负责性能测试技术、方法和工具的研究及推广，推进性能测试能力建设。\n\n\n1、熟练掌握LoadRunner、Jmeter等性能测试工具及应用；\n2、熟练掌握性能监控技术，能够利用Prometheus、nmon、Arthas、jvisualvm等系统监控工具对应用、数据库、中间件等的系统资源进行监控，能够利用pinpoint、skywalking等APM工具进行应用链路追踪；\n3、熟悉系统主流技术架构，对分布式、微服务、云原生、高可用及多活等技术架构有一定的理解和应用；\n4、具有一定的应用软件开发基础，熟悉Java、Python、C++等至少一门主流编程语言；\n5、了解TD/TxSQL、Oracle、Informix等数据库，Linux、AIX等操作系统，Weblogic、NG、ZooKeeper、Redis、MQ等中间件的应用性能和参数调优；\n6、具备性能分析能力，能定位性能问题，提出性能优化方案或意见。\n\n注：有金融业务经验的优先，包括但不限于零售金融，企业金融，同业金融等业务经验。', NULL, NULL, NULL);
INSERT INTO `t_jobs` VALUES (43, '大数据分析师', 42, '全职', '无需经验', 7000, 12000, '大专', '1.收集并整理销售数据并进行分析。\n2.负责常规业务数据提取、处理及分析工作。\n3.数据库营销活动数据提取和分析。\n4.负责数据处理和通报，并及时反馈。', '五险一金,员工旅游,交通补贴,餐饮补贴,通讯补贴,专业培训,绩效奖金,年终奖金,定期体检', NULL, NULL);
